const path = require('node:path');
const fs = require('../fs-native');
const yaml = require('yaml');
const prompts = require('../prompts');
const csv = require('csv-parse/sync');
const { BMAD_FOLDER_NAME } = require('./shared/path-utils');
const { getInstalledCanonicalIds, isBmadOwnedEntry } = require('./shared/installed-skills');

// Reserved OpenCode slash commands. A skill whose canonicalId collides with
// one of these is skipped during command-pointer generation so it doesn't
// shadow a built-in.
const RESERVED_OPENCODE_COMMANDS = new Set([
  'review',
  'commit',
  'init',
  'help',
  'skills',
  'fast',
  'compact',
  'clear',
  'undo',
  'redo',
  'edit',
  'editor',
  'exit',
  'quit',
  'theme',
  'config',
  'model',
  'session',
]);

// Wrap a description for safe insertion into single-line YAML frontmatter.
// Leaves plain values untouched; double-quotes (and escapes) anything that
// could break YAML parsing or span multiple lines.
function yamlSafeSingleLine(value) {
  const collapsed = String(value)
    .replaceAll(/[\r\n]+/g, ' ')
    .trim();
  const needsQuoting = /[:#'"\\]/.test(collapsed) || /^[!&*?|>%@`[{]/.test(collapsed);
  if (!needsQuoting) return collapsed;
  const escaped = collapsed.replaceAll('\\', '\\\\').replaceAll('"', String.raw`\"`);
  return `"${escaped}"`;
}

// Validate that a canonicalId is a safe basename — no path separators, no
// parent-dir traversal, no leading dots, only the character set we expect.
// Defense-in-depth: the manifest is trusted today, but the value flows
// directly into a file path and a malformed entry should not write outside
// the commands directory.
function isSafeCanonicalId(value) {
  return typeof value === 'string' && /^[a-zA-Z0-9][a-zA-Z0-9_.-]*$/.test(value) && !value.includes('..');
}

// Default body template for command pointer files. Used when a platform's
// installer config doesn't override `commands_body_template`. Matches
// OpenCode's native `@skills/<id>` skill-reference syntax.
const DEFAULT_COMMANDS_BODY_TEMPLATE = '@skills/{canonicalId}';

// Is this skill a persona agent (vs. a workflow/tool/standalone skill)?
// Used by platforms that surface only persona agents (e.g. Copilot's Custom
// Agents picker). Signal: the skill's source `customize.toml` has an
// `[agent]` section. This is the actual configuration source of truth —
// every BMAD persona is configured via [agent] in its customize.toml,
// every workflow uses [workflow], every standalone skill has no
// customize.toml at all. Verified against the full installed manifest:
// catches exactly the 20 description-confirmed personas across BMM, CIS,
// GDS, WDS, TEA, and correctly excludes meta-skills like
// `bmad-agent-builder` (a skill-builder workflow whose canonical id
// contains `-agent-` but which has no [agent] section because it isn't a
// persona itself).
//
// Reading the source toml — at install time the source skill directory
// (resolved from manifest record.path) still exists; cleanup runs later
// in the install flow.
async function isAgentSkill(record, bmadDir) {
  if (!record?.path || !bmadDir) return false;
  const bmadFolderName = path.basename(bmadDir);
  const bmadPrefix = bmadFolderName + '/';
  const relativePath = record.path.startsWith(bmadPrefix) ? record.path.slice(bmadPrefix.length) : record.path;
  const tomlPath = path.join(bmadDir, path.dirname(relativePath), 'customize.toml');
  if (!(await fs.pathExists(tomlPath))) return false;
  try {
    const content = await fs.readFile(tomlPath, 'utf8');
    return /^\[agent\]/m.test(content);
  } catch {
    return false;
  }
}

// Resolve placeholders in a body template. Supported placeholders:
//   {canonicalId}   — the skill's canonical id
//   {target_dir}    — the platform's skill install directory (e.g. .agents/skills)
//   {project-root}  — left as a literal placeholder for the model/tool to expand
//                     at runtime; consistent with PR #1769's templates.
function expandBodyTemplate(template, { canonicalId, targetDir }) {
  return template.replaceAll('{canonicalId}', canonicalId).replaceAll('{target_dir}', targetDir);
}

// The exact body the installer would generate for a given description and
// canonicalId, given the platform's body template. Centralised so both the
// write and the freshness-check paths agree on the canonical form.
function buildCommandPointerBody(description, canonicalId, { template, targetDir }) {
  const bodyText = expandBodyTemplate(template, { canonicalId, targetDir });
  return `---\ndescription: ${yamlSafeSingleLine(description)}\n---\n\n${bodyText}\n`;
}

// Heuristic: does an existing pointer file look like our generator's output
// (and therefore safe to refresh) versus a user-modified file (which we
// preserve)? We check the body shape rather than full equality so that
// description-only edits in the manifest can propagate without trampling
// hand edits to the body.
function looksLikeGeneratorOutput(content, canonicalId, { template, targetDir }) {
  if (typeof content !== 'string') return false;
  const trimmed = content.trim();
  const expectedTail = expandBodyTemplate(template, { canonicalId, targetDir }).trim();
  // Must end with the exact body our generator writes (post-expansion).
  if (!trimmed.endsWith(expectedTail)) return false;
  // Must start with frontmatter containing exactly one description: line.
  const fmMatch = trimmed.match(/^---\n([\S\s]*?)\n---\n/);
  if (!fmMatch) return false;
  const fmLines = fmMatch[1].split('\n').filter((l) => l.length > 0);
  if (fmLines.length !== 1) return false;
  if (!fmLines[0].startsWith('description:')) return false;
  return true;
}

/**
 * Config-driven IDE setup handler
 *
 * This class provides a standardized way to install BMAD artifacts to IDEs
 * based on configuration in platform-codes.yaml. It eliminates the need for
 * individual installer files for each IDE.
 *
 * Features:
 * - Config-driven from platform-codes.yaml
 * - Verbatim skill installation from skill-manifest.csv
 * - IDE-specific marker removal (copilot-instructions, kilo modes, rovodev prompts)
 */
class ConfigDrivenIdeSetup {
  constructor(platformCode, platformConfig) {
    this.name = platformCode;
    this.displayName = platformConfig.name || platformCode;
    this.preferred = platformConfig.preferred || false;
    this.platformConfig = platformConfig;
    this.installerConfig = platformConfig.installer || null;
    this.bmadFolderName = BMAD_FOLDER_NAME;

    // Set configDir from target_dir so detect() works
    this.configDir = this.installerConfig?.target_dir || null;
  }

  setBmadFolderName(bmadFolderName) {
    this.bmadFolderName = bmadFolderName;
  }

  /**
   * Detect whether this IDE already has configuration in the project.
   * Checks for bmad-prefixed entries in target_dir.
   * @param {string} projectDir - Project directory
   * @returns {Promise<boolean>}
   */
  async detect(projectDir) {
    if (!this.configDir) return false;

    const root = projectDir || process.cwd();
    const dir = path.join(root, this.configDir);
    if (!(await fs.pathExists(dir))) return false;

    let entries;
    try {
      entries = await fs.readdir(dir);
    } catch {
      return false;
    }

    const bmadDir = await this._findBmadDir(root);
    const canonicalIds = await getInstalledCanonicalIds(bmadDir);
    return entries.some((e) => isBmadOwnedEntry(e, canonicalIds));
  }

  /**
   * Main setup method - called by IdeManager
   * @param {string} projectDir - Project directory
   * @param {string} bmadDir - BMAD installation directory
   * @param {Object} options - Setup options
   * @returns {Promise<Object>} Setup result
   */
  async setup(projectDir, bmadDir, options = {}) {
    // Check for BMAD files in ancestor directories that would cause duplicates
    if (this.installerConfig?.ancestor_conflict_check) {
      const conflict = await this.findAncestorConflict(projectDir);
      if (conflict) {
        await prompts.log.error(
          `Found existing BMAD skills in ancestor installation: ${conflict}\n` +
            `  ${this.name} inherits skills from parent directories, so this would cause duplicates.\n` +
            `  Please remove the BMAD files from that directory first:\n` +
            `    rm -rf "${conflict}"/bmad*`,
        );
        return {
          success: false,
          reason: 'ancestor-conflict',
          error: `Ancestor conflict: ${conflict}`,
          conflictDir: conflict,
        };
      }
    }

    if (!options.silent) await prompts.log.info(`Setting up ${this.name}...`);

    // Clean up any old BMAD installation first
    await this.cleanup(projectDir, options, bmadDir);

    if (!this.installerConfig) {
      return { success: false, reason: 'no-config' };
    }

    // When a peer platform in the same install batch owns this target_dir,
    // skip the skill write — the peer has already populated it. Command
    // pointers, however, write to a separate per-IDE directory and must
    // still be generated for this IDE; they are not deduped across peers.
    if (options.skipTarget) {
      const results = { skills: 0, sharedTargetHandledByPeer: true };
      if (this.installerConfig.commands_target_dir) {
        results.commands = await this.installCommandPointers(projectDir, bmadDir, this.installerConfig, options);
      }
      return { success: true, results };
    }

    if (this.installerConfig.target_dir) {
      return this.installToTarget(projectDir, bmadDir, this.installerConfig, options);
    }

    return { success: false, reason: 'invalid-config' };
  }

  /**
   * Install to a single target directory
   * @param {string} projectDir - Project directory
   * @param {string} bmadDir - BMAD installation directory
   * @param {Object} config - Installation configuration
   * @param {Object} options - Setup options
   * @returns {Promise<Object>} Installation result
   */
  async installToTarget(projectDir, bmadDir, config, options) {
    const { target_dir } = config;
    const targetPath = path.join(projectDir, target_dir);
    await fs.ensureDir(targetPath);

    this.skillWriteTracker = new Set();
    const results = { skills: 0 };

    results.skills = await this.installVerbatimSkills(projectDir, bmadDir, targetPath, config);
    results.skillDirectories = this.skillWriteTracker.size;

    if (config.commands_target_dir) {
      results.commands = await this.installCommandPointers(projectDir, bmadDir, config, options);
    }

    await this.printSummary(results, target_dir, options);
    this.skillWriteTracker = null;
    return { success: true, results };
  }

  /**
   * Generate per-skill command pointer files for IDEs that surface commands
   * separately from skills (e.g. OpenCode's `.opencode/commands/<name>.md`).
   *
   * Each pointer is a tiny markdown file whose body is `@skills/<canonicalId>`
   * so invoking `/<canonicalId>` routes the user straight to the skill instead
   * of forcing them through a `/skills` menu.
   *
   * Skips:
   *  - Names that collide with reserved built-in slash commands.
   *  - canonicalIds that aren't safe basename-only identifiers (defense
   *    against path traversal even though the manifest is currently trusted).
   *  - Existing files whose body looks user-modified (preserves hand edits);
   *    pointer files matching the generator pattern get overwritten so that
   *    description changes in skill-manifest.csv propagate on re-install.
   *
   * Per-file write failures are recorded and reported but do not abort the
   * rest of the install — pointer files are a non-essential adjunct to the
   * skill copy that already succeeded.
   *
   * @param {string} projectDir
   * @param {string} bmadDir
   * @param {Object} config - Installer config; reads commands_target_dir.
   * @param {Object} options - Setup options. forceCommands overwrites existing
   *   files unconditionally (including hand-modified ones).
   * @returns {Promise<Object>} { created, updated, skippedExisting, skippedCollision, skippedInvalidId, writeFailures, fallbackDescription }
   */
  async installCommandPointers(projectDir, bmadDir, config, options = {}) {
    const result = {
      created: 0,
      updated: 0,
      skippedExisting: 0,
      skippedCollision: 0,
      skippedInvalidId: 0,
      skippedFiltered: 0,
      writeFailures: 0,
      fallbackDescription: 0,
    };

    const csvPath = path.join(bmadDir, '_config', 'skill-manifest.csv');
    if (!(await fs.pathExists(csvPath))) return result;

    const commandsPath = path.join(projectDir, config.commands_target_dir);
    await fs.ensureDir(commandsPath);

    // Per-platform pointer-file shape, all overrideable in platform-codes.yaml.
    const extension = config.commands_extension || '.md';
    const template = config.commands_body_template || DEFAULT_COMMANDS_BODY_TEMPLATE;
    const targetDir = config.target_dir;
    const filter = config.commands_filter || null;

    const csvContent = await fs.readFile(csvPath, 'utf8');
    const records = csv.parse(csvContent, { columns: true, skip_empty_lines: true });

    for (const record of records) {
      const canonicalId = record.canonicalId;
      if (!canonicalId) continue;

      // Defensive basename validation. canonicalId comes from a trusted
      // manifest today, but the value flows directly into a file path —
      // reject anything that could escape commands_target_dir.
      if (!isSafeCanonicalId(canonicalId)) {
        result.skippedInvalidId++;
        continue;
      }

      // Optional per-platform filter: surfaces that should only show
      // persona agents (e.g. Copilot's Custom Agents picker) skip
      // workflow/tool skills here so the picker isn't cluttered with
      // 90+ unrelated entries.
      if (filter === 'agents-only' && !(await isAgentSkill(record, bmadDir))) {
        result.skippedFiltered++;
        continue;
      }

      // Reserved-name guard is OpenCode-specific. Other adapters that opt
      // into commands_target_dir later should declare their own reserved
      // set rather than inheriting OpenCode's.
      if (this.name === 'opencode' && RESERVED_OPENCODE_COMMANDS.has(canonicalId)) {
        result.skippedCollision++;
        continue;
      }

      let description = (record.description || '').trim();
      if (!description) {
        description = `Run the ${canonicalId} skill`;
        result.fallbackDescription++;
      }

      const body = buildCommandPointerBody(description, canonicalId, { template, targetDir });
      const commandFile = path.join(commandsPath, `${canonicalId}${extension}`);

      // If a pointer file already exists, decide whether to overwrite based
      // on whether it looks like generator output (description-only diff) or
      // a user-modified file. forceCommands overrides this protection.
      if (!options.forceCommands && (await fs.pathExists(commandFile))) {
        let existing;
        try {
          existing = await fs.readFile(commandFile, 'utf8');
        } catch {
          // Treat unreadable as user-owned and skip — safer than overwriting.
          result.skippedExisting++;
          continue;
        }

        if (existing === body) {
          // No-op idempotent re-run.
          result.skippedExisting++;
          continue;
        }
        if (looksLikeGeneratorOutput(existing, canonicalId, { template, targetDir })) {
          // Description (or other generated bit) has changed; refresh in place.
          try {
            await fs.writeFile(commandFile, body, 'utf8');
            result.updated++;
          } catch (error) {
            result.writeFailures++;
            if (!options.silent) {
              await prompts.log.warn(`Failed to update command pointer ${canonicalId}${extension}: ${error.message}`);
            }
          }
          continue;
        }
        // Hand-modified pointer — preserve it.
        result.skippedExisting++;
        continue;
      }

      try {
        await fs.writeFile(commandFile, body, 'utf8');
        result.created++;
      } catch (error) {
        result.writeFailures++;
        if (!options.silent) {
          await prompts.log.warn(`Failed to write command pointer ${canonicalId}${extension}: ${error.message}`);
        }
      }
    }

    return result;
  }

  /**
   * Install verbatim native SKILL.md directories from skill-manifest.csv.
   * Copies the entire source directory as-is into the IDE skill directory.
   * The source SKILL.md is used directly — no frontmatter transformation or file generation.
   * @param {string} projectDir - Project directory
   * @param {string} bmadDir - BMAD installation directory
   * @param {string} targetPath - Target skills directory
   * @param {Object} config - Installation configuration
   * @returns {Promise<number>} Count of skills installed
   */
  async installVerbatimSkills(projectDir, bmadDir, targetPath, config) {
    const bmadFolderName = path.basename(bmadDir);
    const bmadPrefix = bmadFolderName + '/';
    const csvPath = path.join(bmadDir, '_config', 'skill-manifest.csv');

    if (!(await fs.pathExists(csvPath))) return 0;

    const csvContent = await fs.readFile(csvPath, 'utf8');
    const records = csv.parse(csvContent, {
      columns: true,
      skip_empty_lines: true,
    });

    let count = 0;

    for (const record of records) {
      const canonicalId = record.canonicalId;
      if (!canonicalId) continue;

      // Derive source directory from path column
      // path is like "_bmad/bmm/workflows/bmad-quick-flow/bmad-build-new-preview/SKILL.md"
      // Strip bmadFolderName prefix and join with bmadDir, then get dirname
      const relativePath = record.path.startsWith(bmadPrefix) ? record.path.slice(bmadPrefix.length) : record.path;
      const sourceFile = path.join(bmadDir, relativePath);
      const sourceDir = path.dirname(sourceFile);

      if (!(await fs.pathExists(sourceDir))) continue;

      // Clean target before copy to prevent stale files
      const skillDir = path.join(targetPath, canonicalId);
      await fs.remove(skillDir);
      await fs.ensureDir(skillDir);
      this.skillWriteTracker?.add(canonicalId);

      // Copy all skill files, filtering OS/editor artifacts and Python caches recursively
      const skipPatterns = new Set(['.DS_Store', 'Thumbs.db', 'desktop.ini', '__pycache__']);
      const skipSuffixes = ['~', '.swp', '.swo', '.bak', '.pyc', '.pyo'];
      const filter = (src) => {
        const name = path.basename(src);
        if (src === sourceDir) return true;
        if (skipPatterns.has(name)) return false;
        if (name.startsWith('.') && name !== '.gitkeep') return false;
        if (skipSuffixes.some((s) => name.endsWith(s))) return false;
        return true;
      };
      await fs.copy(sourceDir, skillDir, { filter });

      count++;
    }

    return count;
  }

  /**
   * Print installation summary
   * @param {Object} results - Installation results
   * @param {string} targetDir - Target directory (relative)
   */
  async printSummary(results, targetDir, options = {}) {
    if (options.silent) return;
    const count = results.skillDirectories || results.skills || 0;
    if (count > 0) {
      await prompts.log.success(`${this.name} configured: ${count} skills → ${targetDir}`);
    }
    const cmd = results.commands;
    if (cmd && (cmd.created > 0 || cmd.updated > 0) && this.installerConfig?.commands_target_dir) {
      const total = cmd.created + cmd.updated;
      const detail = cmd.updated > 0 ? `${cmd.created} new, ${cmd.updated} refreshed` : `${total}`;
      await prompts.log.success(`${this.name} commands: ${detail} → ${this.installerConfig.commands_target_dir}`);
      if (cmd.skippedCollision > 0) {
        await prompts.log.message(`  (${cmd.skippedCollision} skipped — name collides with reserved slash command)`);
      }
      if (cmd.writeFailures > 0) {
        await prompts.log.warn(`  (${cmd.writeFailures} pointer writes failed — see warnings above)`);
      }
    }
  }

  /**
   * Cleanup IDE configuration
   * @param {string} projectDir - Project directory
   */
  async cleanup(projectDir, options = {}, bmadDir = null) {
    const resolvedBmadDir = bmadDir || (await this._findBmadDir(projectDir));

    // Build removal set: previously installed skills + removals.txt entries
    let removalSet;
    if (options.previousSkillIds) {
      // Install/update flow: use pre-captured skill IDs (before manifest was overwritten)
      removalSet = new Set(options.previousSkillIds);
      if (resolvedBmadDir) {
        const removals = await this.loadRemovalLists(resolvedBmadDir);
        for (const entry of removals) removalSet.add(entry);
      }
    } else if (resolvedBmadDir) {
      // Uninstall flow: read from current skill-manifest.csv + removals.txt
      removalSet = await this._buildUninstallSet(resolvedBmadDir);
    } else {
      removalSet = new Set();
    }

    // Strip BMAD markers from copilot-instructions.md if present
    if (this.name === 'github-copilot') {
      await this.cleanupCopilotInstructions(projectDir, options);
    }

    // Strip BMAD modes from .kilocodemodes if present
    if (this.name === 'kilo') {
      await this.cleanupKiloModes(projectDir, options);
    }

    // Strip BMAD entries from .rovodev/prompts.yml if present
    if (this.name === 'rovo-dev') {
      await this.cleanupRovoDevPrompts(projectDir, options);
    }

    // Clean generated command pointer files in commands_target_dir.
    // Mirrors target_dir cleanup so uninstalls and skill removals don't
    // leave dangling /<canonicalId> commands pointing at missing skills.
    // Runs regardless of skipTarget — command pointers live in a per-IDE
    // directory and are not deduped across peers, so a peer-owned shared
    // skills directory does not protect this IDE's command pointers from
    // cleanup. The "currently active" set is passed so install-flow cleanup
    // (where removalSet contains skills that will be re-added moments later)
    // doesn't trample hand-edited pointers; install-flow cleanup will only
    // delete pointers for skills that are not in the new manifest.
    if (this.installerConfig?.commands_target_dir) {
      // In the install/update flow (signal: previousSkillIds was passed),
      // spare pointers whose canonicalId is still in the manifest so hand
      // edits survive a routine reinstall. In the uninstall flow (no
      // previousSkillIds — full uninstall or per-IDE removal via
      // cleanupByList), don't spare anything; the IDE itself is going away,
      // so its pointers should go with it.
      const isInstallFlow = !!options.previousSkillIds;
      const activeSkillIds = isInstallFlow ? await this._readActiveSkillIds(resolvedBmadDir) : new Set();
      const extension = this.installerConfig.commands_extension || '.md';
      await this.cleanupCommandPointers(
        projectDir,
        this.installerConfig.commands_target_dir,
        options,
        removalSet,
        activeSkillIds,
        extension,
      );
    }

    // Skip target_dir cleanup when a peer platform owns this directory
    // (set during dedup'd install or when uninstalling one of several
    // platforms that share the same target_dir).
    if (options.skipTarget) return;

    // Clean current target directory
    if (this.installerConfig?.target_dir) {
      await this.cleanupTarget(projectDir, this.installerConfig.target_dir, options, removalSet);
    }
  }

  /**
   * Find the _bmad directory in a project
   * @param {string} projectDir - Project directory
   * @returns {string|null} Path to bmad dir or null
   */
  async _findBmadDir(projectDir) {
    const bmadDir = path.join(projectDir, BMAD_FOLDER_NAME);
    return (await fs.pathExists(bmadDir)) ? bmadDir : null;
  }

  /**
   * Build the full set of entries to remove for uninstall.
   * Reads skill-manifest.csv to know exactly what was installed, plus removal lists.
   * @param {string} bmadDir - BMAD installation directory
   * @returns {Set<string>} Set of entries to remove
   */
  async _buildUninstallSet(bmadDir) {
    const removals = await this.loadRemovalLists(bmadDir);

    // Also add all currently installed skills from skill-manifest.csv
    const csvPath = path.join(bmadDir, '_config', 'skill-manifest.csv');
    try {
      if (await fs.pathExists(csvPath)) {
        const content = await fs.readFile(csvPath, 'utf8');
        const records = csv.parse(content, { columns: true, skip_empty_lines: true });
        for (const record of records) {
          if (record.canonicalId) {
            removals.add(record.canonicalId);
          }
        }
      }
    } catch {
      // If we can't read the manifest, we still have the removal lists
    }

    return removals;
  }

  /**
   * Load removal lists from all module sources in the bmad directory.
   * Each module can have an optional removals.txt listing entries to remove.
   * @param {string} bmadDir - BMAD installation directory
   * @returns {Set<string>} Set of entries to remove
   */
  async loadRemovalLists(bmadDir) {
    const removals = new Set();
    const { getProjectRoot } = require('../project-root');

    // Read project-level removals.txt (covers core and bmm)
    const projectRemovalsPath = path.join(getProjectRoot(), 'removals.txt');
    await this._readRemovalFile(projectRemovalsPath, removals);

    // Read per-module removals.txt from installed module directories
    try {
      const entries = await fs.readdir(bmadDir);
      for (const entry of entries) {
        if (entry.startsWith('_')) continue;
        const removalPath = path.join(bmadDir, entry, 'removals.txt');
        await this._readRemovalFile(removalPath, removals);
      }
    } catch {
      // bmadDir may not exist yet on fresh install
    }

    return removals;
  }

  /**
   * Read a removals.txt file and add entries to the set
   * @param {string} filePath - Path to removals.txt
   * @param {Set<string>} removals - Set to add entries to
   */
  async _readRemovalFile(filePath, removals) {
    try {
      if (await fs.pathExists(filePath)) {
        const content = await fs.readFile(filePath, 'utf8');
        for (const line of content.split('\n')) {
          const trimmed = line.trim();
          if (trimmed && !trimmed.startsWith('#')) {
            removals.add(trimmed);
          }
        }
      }
    } catch {
      // Optional file — ignore errors
    }
  }

  /**
   * Cleanup generated command pointer files for entries in removalSet.
   * Symmetric counterpart to installCommandPointers — removes
   * `<canonicalId><extension>` files whose canonicalId is in the set. Removes
   * the commands directory entirely if it ends up empty.
   * @param {string} projectDir
   * @param {string} commandsTargetDir - Relative dir (e.g. .opencode/commands)
   * @param {Object} options
   * @param {Set<string>} removalSet - canonicalIds whose pointer files to remove
   * @param {Set<string>} [activeSkillIds] - canonicalIds present in the
   *   current manifest. Pointers for IDs in this set are spared so an
   *   install-flow cleanup (where removalSet === previousSkillIds and the
   *   same skills are about to be re-installed) doesn't wipe hand-edited
   *   pointer files. Pass an empty set or omit to delete every match in
   *   removalSet (uninstall flow).
   * @param {string} [extension] - Pointer file extension (default '.md');
   *   matches the platform's commands_extension config value so cleanup
   *   correctly identifies pointer files for IDEs whose convention isn't .md
   *   (e.g. Copilot's `.agent.md`).
   */
  async cleanupCommandPointers(
    projectDir,
    commandsTargetDir,
    options = {},
    removalSet = new Set(),
    activeSkillIds = new Set(),
    extension = '.md',
  ) {
    if (!removalSet || removalSet.size === 0) return;

    const commandsPath = path.join(projectDir, commandsTargetDir);
    if (!(await fs.pathExists(commandsPath))) return;

    let entries;
    try {
      entries = await fs.readdir(commandsPath);
    } catch {
      return;
    }

    for (const entry of entries) {
      if (!entry.endsWith(extension)) continue;
      const canonicalId = entry.slice(0, -extension.length);
      if (!removalSet.has(canonicalId)) continue;
      // Spare pointers for skills that are still in the manifest; the
      // install pass will refresh them in place if their content has gone
      // stale, while preserving hand edits.
      if (activeSkillIds.has(canonicalId)) continue;
      try {
        await fs.remove(path.join(commandsPath, entry));
      } catch {
        // Skip files we can't remove.
      }
    }

    // Remove the commands directory if we emptied it.
    try {
      const remaining = await fs.readdir(commandsPath);
      if (remaining.length === 0) {
        await fs.remove(commandsPath);
      }
    } catch {
      // Directory may already be gone.
    }
  }

  /**
   * Read the canonicalIds currently present in the skill-manifest.csv.
   * Used by cleanup to distinguish "re-install of an existing skill"
   * (preserve pointer) from "skill truly being removed" (delete pointer).
   * @param {string|null} bmadDir
   * @returns {Promise<Set<string>>}
   */
  async _readActiveSkillIds(bmadDir) {
    const ids = new Set();
    if (!bmadDir) return ids;
    const csvPath = path.join(bmadDir, '_config', 'skill-manifest.csv');
    if (!(await fs.pathExists(csvPath))) return ids;
    try {
      const content = await fs.readFile(csvPath, 'utf8');
      const records = csv.parse(content, { columns: true, skip_empty_lines: true });
      for (const record of records) {
        if (record.canonicalId) ids.add(record.canonicalId);
      }
    } catch {
      // Manifest unreadable — return an empty set so cleanup falls back to
      // the conservative "delete what removalSet says" behavior.
    }
    return ids;
  }

  /**
   * Cleanup a specific target directory.
   * When removalSet is provided, only removes entries in that set.
   * When removalSet is null (legacy dirs), removes all bmad-prefixed entries.
   * @param {string} projectDir - Project directory
   * @param {string} targetDir - Target directory to clean
   * @param {Object} options - Cleanup options
   * @param {Set<string>|null} removalSet - Entries to remove, or null for legacy prefix matching
   */
  async cleanupTarget(projectDir, targetDir, options = {}, removalSet = new Set()) {
    const targetPath = path.join(projectDir, targetDir);

    if (!(await fs.pathExists(targetPath))) {
      return;
    }

    if (removalSet && removalSet.size === 0) {
      return;
    }

    let entries;
    try {
      entries = await fs.readdir(targetPath);
    } catch {
      return;
    }

    if (!entries || !Array.isArray(entries)) {
      return;
    }

    let removedCount = 0;

    for (const entry of entries) {
      if (!entry || typeof entry !== 'string') continue;

      // Always preserve bmad-os-* utility skills regardless of cleanup mode
      if (entry.startsWith('bmad-os-')) continue;

      // Surgical removal from set, or fallback to manifest+prefix detection when null
      const shouldRemove = removalSet ? removalSet.has(entry) : isBmadOwnedEntry(entry, null);

      if (shouldRemove) {
        try {
          await fs.remove(path.join(targetPath, entry));
          removedCount++;
        } catch {
          // Skip entries that can't be removed
        }
      }
    }

    // Only log cleanup when it's not a routine reinstall (legacy dir cleanup or actual removals)
    // Suppress for current target_dir since it's always cleaned before a fresh write

    // Remove empty directory after cleanup
    if (removedCount > 0) {
      try {
        const remaining = await fs.readdir(targetPath);
        if (remaining.length === 0) {
          await fs.remove(targetPath);
        }
      } catch {
        // Directory may already be gone or in use
      }
    }
  }

  /**
   * Strip BMAD-owned content from .github/copilot-instructions.md.
   * The old custom installer injected content between <!-- BMAD:START --> and <!-- BMAD:END --> markers.
   * Deletes the file if nothing remains. Restores .bak backup if one exists.
   */
  async cleanupCopilotInstructions(projectDir, options = {}) {
    const filePath = path.join(projectDir, '.github', 'copilot-instructions.md');

    if (!(await fs.pathExists(filePath))) return;

    try {
      const content = await fs.readFile(filePath, 'utf8');
      const startIdx = content.indexOf('<!-- BMAD:START -->');
      const endIdx = content.indexOf('<!-- BMAD:END -->');

      if (startIdx === -1 || endIdx === -1 || endIdx <= startIdx) return;

      const cleaned = content.slice(0, startIdx) + content.slice(endIdx + '<!-- BMAD:END -->'.length);

      if (cleaned.trim().length === 0) {
        await fs.remove(filePath);
        const backupPath = `${filePath}.bak`;
        if (await fs.pathExists(backupPath)) {
          await fs.rename(backupPath, filePath);
          if (!options.silent) await prompts.log.message('  Restored copilot-instructions.md from backup');
        }
      } else {
        await fs.writeFile(filePath, cleaned, 'utf8');
        const backupPath = `${filePath}.bak`;
        if (await fs.pathExists(backupPath)) await fs.remove(backupPath);
      }

      if (!options.silent) await prompts.log.message('  Cleaned BMAD markers from copilot-instructions.md');
    } catch {
      if (!options.silent) await prompts.log.warn('  Warning: Could not clean BMAD markers from copilot-instructions.md');
    }
  }

  /**
   * Strip BMAD-owned modes from .kilocodemodes.
   * The old custom kilo.js installer added modes with slug starting with 'bmad-'.
   * Parses YAML, filters out BMAD modes, rewrites. Leaves file as-is on parse failure.
   */
  async cleanupKiloModes(projectDir, options = {}) {
    const kiloModesPath = path.join(projectDir, '.kilocodemodes');

    if (!(await fs.pathExists(kiloModesPath))) return;

    const content = await fs.readFile(kiloModesPath, 'utf8');

    let config;
    try {
      config = yaml.parse(content) || {};
    } catch {
      if (!options.silent) await prompts.log.warn('  Warning: Could not parse .kilocodemodes for cleanup');
      return;
    }

    if (!Array.isArray(config.customModes)) return;

    const originalCount = config.customModes.length;
    config.customModes = config.customModes.filter((mode) => mode && (!mode.slug || !mode.slug.startsWith('bmad-')));
    const removedCount = originalCount - config.customModes.length;

    if (removedCount > 0) {
      try {
        await fs.writeFile(kiloModesPath, yaml.stringify(config, { lineWidth: 0 }));
        if (!options.silent) await prompts.log.message(`  Removed ${removedCount} BMAD modes from .kilocodemodes`);
      } catch {
        if (!options.silent) await prompts.log.warn('  Warning: Could not write .kilocodemodes during cleanup');
      }
    }
  }

  /**
   * Strip BMAD-owned entries from .rovodev/prompts.yml.
   * The old custom rovodev.js installer registered workflows in prompts.yml.
   * Parses YAML, filters out entries with name starting with 'bmad-', rewrites.
   * Removes the file if no entries remain.
   */
  async cleanupRovoDevPrompts(projectDir, options = {}) {
    const promptsPath = path.join(projectDir, '.rovodev', 'prompts.yml');

    if (!(await fs.pathExists(promptsPath))) return;

    const content = await fs.readFile(promptsPath, 'utf8');

    let config;
    try {
      config = yaml.parse(content) || {};
    } catch {
      if (!options.silent) await prompts.log.warn('  Warning: Could not parse prompts.yml for cleanup');
      return;
    }

    if (!Array.isArray(config.prompts)) return;

    const originalCount = config.prompts.length;
    config.prompts = config.prompts.filter((entry) => entry && (!entry.name || !entry.name.startsWith('bmad-')));
    const removedCount = originalCount - config.prompts.length;

    if (removedCount > 0) {
      try {
        if (config.prompts.length === 0) {
          await fs.remove(promptsPath);
        } else {
          await fs.writeFile(promptsPath, yaml.stringify(config, { lineWidth: 0 }));
        }
        if (!options.silent) await prompts.log.message(`  Removed ${removedCount} BMAD entries from prompts.yml`);
      } catch {
        if (!options.silent) await prompts.log.warn('  Warning: Could not write prompts.yml during cleanup');
      }
    }
  }

  /**
   * Check ancestor directories for existing BMAD files in the same target_dir.
   * IDEs like Claude Code inherit commands from parent directories, so an existing
   * installation in an ancestor would cause duplicate commands.
   * @param {string} projectDir - Project directory being installed to
   * @returns {Promise<string|null>} Path to conflicting directory, or null if clean
   */
  async findAncestorConflict(projectDir) {
    const targetDir = this.installerConfig?.target_dir;
    if (!targetDir) return null;

    const resolvedProject = await fs.realpath(path.resolve(projectDir));
    let current = path.dirname(resolvedProject);
    const root = path.parse(current).root;

    while (current !== root && current.length > root.length) {
      const candidatePath = path.join(current, targetDir);
      try {
        if (await fs.pathExists(candidatePath)) {
          const entries = await fs.readdir(candidatePath);
          const ancestorBmadDir = await this._findBmadDir(current);
          const canonicalIds = await getInstalledCanonicalIds(ancestorBmadDir);
          if (entries.some((e) => isBmadOwnedEntry(e, canonicalIds))) {
            return candidatePath;
          }
        }
      } catch {
        // Can't read directory — skip
      }
      current = path.dirname(current);
    }

    return null;
  }
}

module.exports = { ConfigDrivenIdeSetup };

const { spawnSync } = require('node:child_process');
const prompts = require('../prompts');

// `uv` (https://docs.astral.sh/uv/) is how BMAD runs the Python scripts its
// skills shell out to: `uv run <script>` resolves the interpreter and any
// dependencies on demand from the script's own `requires-python` metadata, so
// skills don't have to assume a particular `python3` is on PATH.
//
// As of v6.11.0 this is a requirement, not a preference: the rendered skills
// (`bmad-build`, `bmad-build-auto`) render through `render_skill.py` and HALT
// on activation if `uv` is unavailable — there is no interpreter fallback.
//
// The check still never blocks the install. Core-only, docs-only, and CI
// installs are legitimate and never touch a rendered skill, so a missing `uv`
// must not fail the run. What it does is tell the truth about what will and
// will not work afterwards, here and again in the post-install summary.
const RUNTIME_COMMAND = 'uv';

// Probed only when `uv` is absent. Some skills still invoke the interpreter
// directly (`python3 .../resolve_customization.py`), and those scripts declare
// `requires-python = ">=3.11"` — `resolve_config.py` hard-exits below it
// because `tomllib` is a 3.11 stdlib addition. When `uv` is present it
// provisions its own interpreter and whatever `python3` resolves to on PATH is
// irrelevant, so probing it then would report a problem that doesn't exist.
const PYTHON_COMMAND = 'python3';
const MIN_PYTHON = { major: 3, minor: 11 };

/**
 * Parse `uv --version` output into version parts.
 * Example outputs: "uv 0.5.31", "uv 0.5.31 (Homebrew 2025-02-12)".
 * @param {string} output - stdout/stderr from `uv --version`
 * @returns {{major: number, minor: number, patch: number, raw: string}|null}
 */
function parseUvVersion(output) {
  if (!output) return null;
  const match = output.match(/uv\s+(\d+)\.(\d+)(?:\.(\d+))?/i);
  if (!match) return null;
  return {
    major: Number(match[1]),
    minor: Number(match[2]),
    patch: Number(match[3] || 0),
    raw: `${match[1]}.${match[2]}.${match[3] || 0}`,
  };
}

/**
 * Parse `python3 --version` output into version parts.
 * Example outputs: "Python 3.11.7", "Python 3.13.0rc1".
 * @param {string} output - stdout/stderr from `python3 --version`
 * @returns {{major: number, minor: number, patch: number, raw: string}|null}
 */
function parsePythonVersion(output) {
  if (!output) return null;
  const match = output.match(/Python\s+(\d+)\.(\d+)(?:\.(\d+))?/i);
  if (!match) return null;
  return {
    major: Number(match[1]),
    minor: Number(match[2]),
    patch: Number(match[3] || 0),
    raw: `${match[1]}.${match[2]}.${match[3] || 0}`,
  };
}

/**
 * Whether a parsed Python version satisfies the 3.11+ floor the scripts declare.
 * @param {{major: number, minor: number}|null} version
 * @returns {boolean}
 */
function pythonMeetsMinimum(version) {
  if (!version) return false;
  if (version.major !== MIN_PYTHON.major) return version.major > MIN_PYTHON.major;
  return version.minor >= MIN_PYTHON.minor;
}

/**
 * Run `<command> --version` and hand the combined output to a parser.
 * @param {string} command
 * @param {(output: string) => Object|null} parse
 * @returns {{version: Object}|null}
 */
function probeVersion(command, parse) {
  let result;
  try {
    result = spawnSync(command, ['--version'], {
      encoding: 'utf8',
      timeout: 5000,
      windowsHide: true,
    });
  } catch {
    return null;
  }
  if (!result || result.error) return null;
  const version = parse(`${result.stdout || ''}\n${result.stderr || ''}`);
  return version ? { version } : null;
}

/**
 * Probe the local environment for `uv`.
 * @returns {{version: {major: number, minor: number, patch: number, raw: string}}|null}
 */
function detectUv() {
  return probeVersion(RUNTIME_COMMAND, parseUvVersion);
}

/**
 * Probe the local environment for `python3`.
 * @returns {{version: {major: number, minor: number, patch: number, raw: string}}|null}
 */
function detectPython3() {
  return probeVersion(PYTHON_COMMAND, parsePythonVersion);
}

function setupHints() {
  return [
    '`uv run` provisions the interpreter and dependencies for you — no manual',
    'venv or pip, and no need for a particular python3 on PATH.',
    '',
    'Easiest path: ask your AI agent to "install and set up uv for me".',
    '',
    'Or install it yourself:',
    '  macOS/Linux:  curl -LsSf https://astral.sh/uv/install.sh | sh',
    '  Windows:      powershell -c "irm https://astral.sh/uv/install.ps1 | iex"',
    '  Homebrew:     brew install uv',
    '  Docs:         https://docs.astral.sh/uv/getting-started/installation/',
  ].join('\n');
}

/**
 * Describe what a missing `uv` leaves working, based on the `python3` fallback.
 *
 * With `uv` gone the rendered skills are lost either way; the only question is
 * whether the skills that invoke the interpreter directly still run, and that
 * turns on `python3` being 3.11+.
 *
 * @param {{version: Object}|null} python - result of detectPython3()
 * @returns {string}
 */
function pythonFallbackNote(python) {
  if (!python) {
    return 'No python3 on PATH either, so no Python-backed skill will run.';
  }
  if (pythonMeetsMinimum(python.version)) {
    return (
      `python3 ${python.version.raw} is present, so skills that call the interpreter ` +
      'directly still work — but the rendered skills above stay unavailable.'
    );
  }
  return (
    `python3 ${python.version.raw} is present but below the required ` +
    `${MIN_PYTHON.major}.${MIN_PYTHON.minor}, so no Python-backed skill will run.`
  );
}

/**
 * Check whether `uv` is available and inform the user.
 *
 * Warn-don't-block: a missing `uv` never stops or fails the install, because
 * core-only and CI installs are legitimate and never render a skill. But the
 * warning names the concrete consequence — `bmad-build` and `bmad-build-auto`
 * halt — rather than describing `uv` as a nice-to-have, and `installer.js`
 * repeats it in the post-install summary so it isn't lost in the scrollback.
 *
 * @returns {Promise<{status: 'found'|'missing', detected: Object|null, python: Object|null}>}
 */
async function checkUvEnvironment() {
  // Called via module.exports so tests can stub detection.
  const detected = module.exports.detectUv();

  if (detected) {
    await prompts.log.success(`✅ Python UV check pass (uv ${detected.version.raw} detected).`);
    return { status: 'found', detected, python: null };
  }

  const python = module.exports.detectPython3();

  await prompts.log.warn(
    'uv not found on PATH. BMAD requires it to run the Python scripts its skills\n' +
      'shell out to: bmad-build and bmad-build-auto render through `uv run` and will\n' +
      'HALT on activation without it — there is no interpreter fallback.\n' +
      `${pythonFallbackNote(python)}\n` +
      'The install itself completes either way.',
  );
  await prompts.note(setupHints(), 'uv required');
  return { status: 'missing', detected: null, python };
}

module.exports = {
  checkUvEnvironment,
  detectUv,
  detectPython3,
  parseUvVersion,
  parsePythonVersion,
  pythonMeetsMinimum,
  MIN_PYTHON,
};

const path = require('node:path');
const fs = require('../fs-native');
const { Manifest } = require('./manifest');
const { OfficialModules } = require('../modules/official-modules');
const { IdeManager } = require('../ide/manager');
const { FileOps } = require('../file-ops');
const { Config } = require('./config');
const { getProjectRoot, getSourcePath } = require('../project-root');
const { ManifestGenerator } = require('./manifest-generator');
const prompts = require('../prompts');
const { BMAD_FOLDER_NAME } = require('../ide/shared/path-utils');
const { InstallPaths } = require('./install-paths');
const { ExternalModuleManager } = require('../modules/external-manager');
const { resolveModuleVersion } = require('../modules/version-resolver');
const { MODULE_HELP_CSV_HEADER } = require('../modules/module-help-schema');
const {
  formatRemovedShimNotice,
  formatRetainedShimNotice,
  inferShimPreference,
  readInstalledShims,
  readInstalledSkillIds,
  selectShimOutcome,
} = require('./shim-policy');

const { ExistingInstall } = require('./existing-install');
const { warnPreNativeSkillsLegacy } = require('./legacy-warnings');

class Installer {
  constructor() {
    this.externalModuleManager = new ExternalModuleManager();
    this.manifest = new Manifest();
    this.ideManager = new IdeManager();
    this.fileOps = new FileOps();
    this.installedFiles = new Set(); // Track all installed files
    this.bmadFolderName = BMAD_FOLDER_NAME;
  }

  /**
   * Main installation method
   * @param {Object} config - Installation configuration
   * @param {string} config.directory - Target directory
   * @param {string[]} config.modules - Modules to install (including 'core')
   * @param {string[]} config.ides - IDEs to configure
   */
  async install(originalConfig) {
    let updateState = null;

    try {
      const config = Config.build(originalConfig);
      const paths = await InstallPaths.create(config);
      const officialModules = await OfficialModules.build(config, paths);
      const existingInstall = await ExistingInstall.detect(paths.bmadDir);
      const availableShims = await officialModules.discoverShims(config.modules, {
        channelOptions: config.channelOptions,
      });
      const previousManifest = existingInstall.installed ? await this.manifest.read(paths.bmadDir) : null;
      const installedSkillIds = existingInstall.installed ? await readInstalledSkillIds(paths.bmadDir) : new Set();
      const shimPolicy = {
        available: availableShims.length > 0,
        install: inferShimPreference({
          requested: config.installShims,
          persisted: previousManifest?.installShims,
          availableShims,
          installedSkillIds,
          existing: existingInstall.installed,
        }),
      };

      const installedShims = existingInstall.installed ? await readInstalledShims(paths.bmadDir) : [];
      const { retained: retainedShims, removed: removedShims } = selectShimOutcome({
        installedShims,
        availableShims,
        install: shimPolicy.install,
      });

      // Reported here, not at the prompt, so --yes/--shims/scripted runs get it too.
      if (retainedShims.length > 0) {
        await prompts.note(formatRetainedShimNotice(retainedShims), 'Deprecated shim skills retained');
      }
      if (removedShims.length > 0) {
        await prompts.note(formatRemovedShimNotice(removedShims, { canReinstall: shimPolicy.available }), 'Deprecated shim skills removed');
      }

      // The notices above scroll away on a long install; repeat them in the summary.
      const shimStatus = { retained: retainedShims.length, removed: removedShims.length };

      try {
        await warnPreNativeSkillsLegacy({
          projectRoot: paths.projectRoot,
          existingVersion: existingInstall.installed ? existingInstall.version : null,
        });
      } catch (error) {
        // Legacy-dir scan is informational; never let it abort install.
        await prompts.log.warn(`Warning: Could not check for legacy BMAD entries: ${error.message}`);
      }

      if (existingInstall.installed) {
        await this._removeDeselectedModules(existingInstall, config, paths, originalConfig._preserveModules || []);
        updateState = await this._prepareUpdateState(paths, config, existingInstall, officialModules);
        await this._removeDeselectedIdes(existingInstall, config, paths);
      }

      await this._validateIdeSelection(config);

      // Capture pre-install module versions for from→to display
      const preInstallVersions = new Map();
      if (existingInstall.installed) {
        const existingModules = await this.manifest.getAllModuleVersions(paths.bmadDir);
        for (const mod of existingModules) {
          if (mod.name && mod.version) {
            preInstallVersions.set(mod.name, mod.version);
          }
        }
      }

      // Results collector for consolidated summary
      const results = [];
      const addResult = (step, status, detail = '', meta = {}) => results.push({ step, status, detail, ...meta });

      // Capture previously installed skill rows before they get overwritten
      const preservedModules = originalConfig._preserveModules || [];
      const previousSkillManifestRows = await this._readSkillManifestRows(paths.bmadDir);
      const previousSkillIds = this._getPreviousSkillIdsForCleanup(previousSkillManifestRows, preservedModules);

      const allModules = config.modules || [];

      await this._installAndConfigure(
        config,
        originalConfig,
        paths,
        allModules,
        allModules,
        addResult,
        officialModules,
        previousSkillManifestRows,
        shimPolicy,
      );

      await this._setupIdes(config, allModules, paths, addResult, previousSkillIds);

      // Skills are now in IDE directories — remove redundant copies from _bmad/.
      // Also cleans up skill dirs left by older installer versions.
      await this._cleanupSkillDirs(paths.bmadDir);

      const restoreResult = await this._restoreUserFiles(paths, updateState);

      // Surface any "action needed" post-install messages for installed modules
      // (e.g. run a setup skill) and let the user acknowledge them before the
      // final summary, so "BMAD is ready to use!" stays the last thing shown.
      await this._displayPostInstallMessages(config, officialModules);

      // Render consolidated summary
      await this.renderInstallSummary(results, {
        bmadDir: paths.bmadDir,
        modules: config.modules,
        ides: config.ides,
        customFiles: restoreResult.customFiles.length > 0 ? restoreResult.customFiles : undefined,
        modifiedFiles: restoreResult.modifiedFiles.length > 0 ? restoreResult.modifiedFiles : undefined,
        preInstallVersions,
        shimStatus,
      });

      return {
        success: true,
        path: paths.bmadDir,
        modules: config.modules,
        ides: config.ides,
        projectDir: paths.projectRoot,
      };
    } catch (error) {
      await prompts.log.error('Installation failed');

      // Clean up any temp backup directories that were created before the failure
      try {
        if (updateState?.tempBackupDir && (await fs.pathExists(updateState.tempBackupDir))) {
          await fs.remove(updateState.tempBackupDir);
        }
        if (updateState?.tempModifiedBackupDir && (await fs.pathExists(updateState.tempModifiedBackupDir))) {
          await fs.remove(updateState.tempModifiedBackupDir);
        }
      } catch {
        // Best-effort cleanup — don't mask the original error
      }

      throw error;
    }
  }

  /**
   * Remove modules that were previously installed but are no longer selected.
   * No confirmation — the user's module selection is the decision.
   */
  async _removeDeselectedModules(existingInstall, config, paths, preservedModules = []) {
    const previouslyInstalled = new Set(existingInstall.moduleIds);
    const newlySelected = new Set(config.modules || []);
    const preserved = new Set(preservedModules);
    const toRemove = [...previouslyInstalled].filter((m) => !newlySelected.has(m) && m !== 'core' && !preserved.has(m));

    for (const moduleId of toRemove) {
      const modulePath = paths.moduleDir(moduleId);
      try {
        if (await fs.pathExists(modulePath)) {
          await fs.remove(modulePath);
        }
      } catch (error) {
        await prompts.log.warn(`Warning: Failed to remove ${moduleId}: ${error.message}`);
      }
    }
  }

  /**
   * Fail fast if all selected IDEs are suspended.
   */
  async _validateIdeSelection(config) {
    if (!config.ides || config.ides.length === 0) return;

    await this.ideManager.ensureInitialized();
    const suspendedIdes = config.ides.filter((ide) => {
      const handler = this.ideManager.handlers.get(ide);
      return handler?.platformConfig?.suspended;
    });

    if (suspendedIdes.length > 0 && suspendedIdes.length === config.ides.length) {
      for (const ide of suspendedIdes) {
        const handler = this.ideManager.handlers.get(ide);
        await prompts.log.error(`${handler.displayName || ide}: ${handler.platformConfig.suspended}`);
      }
      throw new Error(
        `All selected tool(s) are suspended: ${suspendedIdes.join(', ')}. Installation aborted to prevent upgrading _bmad/ without a working IDE configuration.`,
      );
    }
  }

  /**
   * Remove IDEs that were previously installed but are no longer selected.
   * No confirmation — the user's IDE selection is the decision.
   */
  async _removeDeselectedIdes(existingInstall, config, paths) {
    const previouslyInstalled = new Set(existingInstall.ides);
    const newlySelected = new Set(config.ides || []);
    const toRemove = [...previouslyInstalled].filter((ide) => !newlySelected.has(ide));

    if (toRemove.length === 0) return;

    // Pass the newly-selected list as remainingIdes so cleanupByList skips
    // target_dir wipes for IDEs whose directory is still owned by a peer
    // (e.g. removing 'cursor' while 'gemini' remains — both share .agents/skills).
    const results = await this.ideManager.cleanupByList(paths.projectRoot, toRemove, {
      remainingIdes: [...newlySelected],
    });

    for (const result of results || []) {
      if (result && result.success === false) {
        await prompts.log.warn(`Warning: Failed to remove ${result.ide}: ${result.error || 'unknown error'}`);
      }
    }
  }

  /**
   * Install modules, create directories, generate configs and manifests.
   */
  async _installAndConfigure(
    config,
    originalConfig,
    paths,
    officialModuleIds,
    allModules,
    addResult,
    officialModules,
    previousSkillManifestRows = [],
    shimPolicy = null,
  ) {
    const isQuickUpdate = config.isQuickUpdate();
    const moduleConfigs = officialModules.moduleConfigs;
    const resolvedShimPolicy = shimPolicy || { available: false, install: false };

    const dirResults = { createdDirs: [], movedDirs: [], createdWdsFolders: [] };

    const installTasks = [];

    installTasks.push({
      title: 'Installing shared scripts',
      task: async () => {
        await this._installSharedScripts(paths);
        addResult('Shared scripts', 'ok');
        return 'Shared scripts installed';
      },
    });

    if (allModules.length > 0) {
      installTasks.push({
        title: isQuickUpdate ? `Updating ${allModules.length} module(s)` : `Installing ${allModules.length} module(s)`,
        task: async (message) => {
          const installedModuleNames = new Set();

          await this._installOfficialModules(config, paths, officialModuleIds, addResult, isQuickUpdate, officialModules, {
            message,
            installedModuleNames,
            shimPolicy: resolvedShimPolicy,
          });

          return `${allModules.length} module(s) ${isQuickUpdate ? 'updated' : 'installed'}`;
        },
      });
    }

    installTasks.push({
      title: 'Creating module directories',
      task: async (message) => {
        const verboseMode = process.env.BMAD_VERBOSE_INSTALL === 'true' || config.verbose;
        const moduleLogger = {
          log: async (msg) => (verboseMode ? await prompts.log.message(msg) : undefined),
          error: async (msg) => await prompts.log.error(msg),
          warn: async (msg) => await prompts.log.warn(msg),
        };

        if (config.modules && config.modules.length > 0) {
          for (const moduleName of config.modules) {
            message(`Setting up ${moduleName}...`);
            const result = await officialModules.createModuleDirectories(moduleName, paths.bmadDir, {
              installedIDEs: config.ides || [],
              moduleConfig: moduleConfigs[moduleName] || {},
              existingModuleConfig: officialModules.existingConfig?.[moduleName] || {},
              coreConfig: moduleConfigs.core || {},
              logger: moduleLogger,
              silent: true,
            });
            if (result) {
              dirResults.createdDirs.push(...result.createdDirs);
              dirResults.movedDirs.push(...(result.movedDirs || []));
              dirResults.createdWdsFolders.push(...result.createdWdsFolders);
            }
          }
        }

        addResult('Module directories', 'ok');
        return 'Module directories created';
      },
    });

    const configTask = {
      title: 'Generating configurations',
      task: async (message) => {
        await this.generateModuleConfigs(paths.bmadDir, moduleConfigs);
        addResult('Configurations', 'ok', 'generated');

        this.installedFiles.add(paths.manifestFile());
        this.installedFiles.add(paths.centralConfig());
        this.installedFiles.add(paths.centralUserConfig());

        message('Generating manifests...');
        const manifestGen = new ManifestGenerator();
        const preservedModules = originalConfig._preserveModules || [];

        const allModulesForManifest = config.isQuickUpdate()
          ? originalConfig._existingModules || allModules || []
          : preservedModules.length > 0
            ? [...allModules, ...preservedModules]
            : allModules || [];

        let modulesForCsvPreserve;
        if (config.isQuickUpdate()) {
          modulesForCsvPreserve = originalConfig._existingModules || allModules || [];
        } else {
          modulesForCsvPreserve = preservedModules.length > 0 ? [...allModules, ...preservedModules] : allModules;
        }

        await this._trackPreservedModuleFiles(paths.bmadDir, preservedModules);

        await manifestGen.generateManifests(paths.bmadDir, allModulesForManifest, [...this.installedFiles], {
          ides: config.ides || [],
          preservedModules: modulesForCsvPreserve,
          moduleConfigs,
          installShims: resolvedShimPolicy.install,
          shimsAvailable: resolvedShimPolicy.available,
        });
        await this._appendPreservedSkillManifestRows(paths.bmadDir, previousSkillManifestRows, preservedModules);

        // Apply post-install --set TOML patches. Runs after writeCentralConfig
        // (inside generateManifests above) so the patch operates on the
        // freshly written `_bmad/config.toml` / `_bmad/config.user.toml`.
        // See `tools/installer/set-overrides.js` for routing rules.
        if (config.setOverrides && Object.keys(config.setOverrides).length > 0) {
          const { applySetOverrides } = require('../set-overrides');
          const applied = await applySetOverrides(config.setOverrides, paths.bmadDir);
          if (applied.length > 0) {
            const summary = applied.map((a) => `${a.module}.${a.key} → ${a.file}`).join(', ');
            await prompts.log.info(`Applied --set overrides: ${summary}`);
          }
        }

        message('Generating help catalog...');
        await this.mergeModuleHelpCatalogs(paths.bmadDir, manifestGen.agents);
        addResult('Help catalog', 'ok');

        return 'Configurations generated';
      },
    };
    installTasks.push(configTask);

    // Run install + dirs first, then render dir output, then run config generation
    const mainTasks = installTasks.filter((t) => t !== configTask);
    await prompts.tasks(mainTasks);

    const color = await prompts.getColor();
    if (dirResults.movedDirs.length > 0) {
      const lines = dirResults.movedDirs.map((d) => `  ${d}`).join('\n');
      await prompts.log.message(color.cyan(`Moved directories:\n${lines}`));
    }
    if (dirResults.createdDirs.length > 0) {
      const lines = dirResults.createdDirs.map((d) => `  ${d}`).join('\n');
      await prompts.log.message(color.yellow(`Created directories:\n${lines}`));
    }
    if (dirResults.createdWdsFolders.length > 0) {
      const lines = dirResults.createdWdsFolders.map((f) => color.dim(`  \u2713 ${f}/`)).join('\n');
      await prompts.log.message(color.cyan(`Created WDS folder structure:\n${lines}`));
    }

    await prompts.tasks([configTask]);
  }

  /**
   * Set up IDE integrations for each selected IDE.
   */
  async _setupIdes(config, allModules, paths, addResult, previousSkillIds = new Set()) {
    if (config.skipIde || !config.ides || config.ides.length === 0) return;

    await this.ideManager.ensureInitialized();
    const validIdes = config.ides.filter((ide) => ide && typeof ide === 'string');

    if (validIdes.length === 0) {
      addResult('IDE configuration', 'warn', 'no valid IDEs selected');
      return;
    }

    const setupResults = await this.ideManager.setupBatch(validIdes, paths.projectRoot, paths.bmadDir, {
      selectedModules: allModules || [],
      verbose: config.verbose,
      previousSkillIds,
    });

    for (const setupResult of setupResults) {
      const ide = setupResult.ide;
      if (setupResult.success) {
        addResult(ide, 'ok', setupResult.detail || '');
      } else {
        addResult(ide, 'error', setupResult.error || 'failed');
      }
    }
  }

  /**
   * Remove skill directories from _bmad/ after IDE installation.
   * Skills are self-contained in IDE directories, so _bmad/ only needs
   * module-level files (config.yaml, _config/, etc.).
   * Also cleans up skill dirs left by older installer versions.
   * @param {string} bmadDir - BMAD installation directory
   */
  async _cleanupSkillDirs(bmadDir) {
    const csv = require('csv-parse/sync');
    const csvPath = path.join(bmadDir, '_config', 'skill-manifest.csv');
    if (!(await fs.pathExists(csvPath))) return;

    const csvContent = await fs.readFile(csvPath, 'utf8');
    const records = csv.parse(csvContent, { columns: true, skip_empty_lines: true });
    const bmadFolderName = path.basename(bmadDir);
    const bmadPrefix = bmadFolderName + '/';

    for (const record of records) {
      if (!record.path) continue;
      const relativePath = record.path.startsWith(bmadPrefix) ? record.path.slice(bmadPrefix.length) : record.path;
      const sourceDir = path.dirname(path.join(bmadDir, relativePath));
      if (await fs.pathExists(sourceDir)) {
        await fs.remove(sourceDir);
        await this._removeEmptyParents(path.dirname(sourceDir), bmadDir);
      }
    }
  }

  /**
   * Remove now-empty parent directories left behind after skill dir cleanup.
   * Walks up from dir, stopping at (and never removing) bmadDir. Best-effort:
   * a directory that vanishes or fills in mid-walk just ends the walk.
   * @param {string} dir - Directory to start walking up from
   * @param {string} bmadDir - BMAD installation directory (boundary)
   */
  async _removeEmptyParents(dir, bmadDir) {
    let current = dir;
    while (true) {
      // Path-boundary check (not a string prefix, so siblings like _bmad2 don't match).
      const rel = path.relative(bmadDir, current);
      if (rel === '' || rel.startsWith('..') || path.isAbsolute(rel)) break;
      try {
        const entries = await fs.readdir(current);
        if (entries.length > 0) break;
        await fs.rmdir(current);
      } catch {
        break;
      }
      current = path.dirname(current);
    }
  }

  async _readSkillManifestRows(bmadDir) {
    const csvPath = path.join(bmadDir, '_config', 'skill-manifest.csv');
    if (!(await fs.pathExists(csvPath))) return [];

    try {
      const csvParse = require('csv-parse/sync');
      const content = await fs.readFile(csvPath, 'utf8');
      return csvParse.parse(content, { columns: true, skip_empty_lines: true });
    } catch (error) {
      await prompts.log.warn(`Failed to parse skill-manifest.csv: ${error.message}`);
      return [];
    }
  }

  _getPreviousSkillIdsForCleanup(previousRows, preservedModules = []) {
    const preservedModuleSet = new Set(preservedModules || []);
    const ids = new Set();
    for (const row of previousRows || []) {
      if (row.canonicalId && !preservedModuleSet.has(row.module)) {
        ids.add(row.canonicalId);
      }
    }
    return ids;
  }

  async _appendPreservedSkillManifestRows(bmadDir, previousRows, preservedModules = []) {
    if (!previousRows || previousRows.length === 0 || preservedModules.length === 0) return;

    const preservedModuleSet = new Set(preservedModules);
    const rowsToPreserve = previousRows.filter((row) => row.canonicalId && row.module && preservedModuleSet.has(row.module));
    if (rowsToPreserve.length === 0) return;

    const csvPath = path.join(bmadDir, '_config', 'skill-manifest.csv');
    if (!(await fs.pathExists(csvPath))) return;

    const currentRows = await this._readSkillManifestRows(bmadDir);
    const activeIds = new Set(currentRows.map((row) => row.canonicalId).filter(Boolean));
    const appendedRows = [];

    for (const row of rowsToPreserve) {
      if (activeIds.has(row.canonicalId)) continue;
      activeIds.add(row.canonicalId);
      appendedRows.push(
        [row.canonicalId, row.name || row.canonicalId, row.description || '', row.module, row.path || '']
          .map((field) => this.escapeCSVField(field))
          .join(','),
      );
    }

    if (appendedRows.length === 0) return;

    const currentContent = await fs.readFile(csvPath, 'utf8');
    const prefix = currentContent.endsWith('\n') ? currentContent : `${currentContent}\n`;
    await fs.writeFile(csvPath, prefix + appendedRows.join('\n') + '\n', 'utf8');
  }

  /**
   * Restore custom and modified files that were backed up before the update.
   * No-op for fresh installs (updateState is null).
   * @param {Object} paths - InstallPaths instance
   * @param {Object|null} updateState - From _prepareUpdateState, or null for fresh installs
   * @returns {Object} { customFiles, modifiedFiles } — lists of restored files
   */
  async _restoreUserFiles(paths, updateState) {
    const noFiles = { customFiles: [], modifiedFiles: [] };

    if (!updateState || (updateState.customFiles.length === 0 && updateState.modifiedFiles.length === 0)) {
      return noFiles;
    }

    let restoredCustomFiles = [];
    let restoredModifiedFiles = [];

    await prompts.tasks([
      {
        title: 'Finalizing installation',
        task: async (message) => {
          if (updateState.customFiles.length > 0) {
            message(`Restoring ${updateState.customFiles.length} custom files...`);

            for (const originalPath of updateState.customFiles) {
              const relativePath = path.relative(paths.bmadDir, originalPath);
              const backupPath = path.join(updateState.tempBackupDir, relativePath);

              if (await fs.pathExists(backupPath)) {
                await fs.ensureDir(path.dirname(originalPath));
                await fs.copy(backupPath, originalPath, { overwrite: true });
              }
            }

            if (updateState.tempBackupDir && (await fs.pathExists(updateState.tempBackupDir))) {
              await fs.remove(updateState.tempBackupDir);
            }

            restoredCustomFiles = updateState.customFiles;
          }

          if (updateState.modifiedFiles.length > 0) {
            restoredModifiedFiles = updateState.modifiedFiles;

            if (updateState.tempModifiedBackupDir && (await fs.pathExists(updateState.tempModifiedBackupDir))) {
              message(`Restoring ${restoredModifiedFiles.length} modified files as .bak...`);

              for (const modifiedFile of restoredModifiedFiles) {
                const relativePath = path.relative(paths.bmadDir, modifiedFile.path);
                const tempBackupPath = path.join(updateState.tempModifiedBackupDir, relativePath);
                const bakPath = modifiedFile.path + '.bak';

                if (await fs.pathExists(tempBackupPath)) {
                  await fs.ensureDir(path.dirname(bakPath));
                  await fs.copy(tempBackupPath, bakPath, { overwrite: true });
                }
              }

              await fs.remove(updateState.tempModifiedBackupDir);
            }
          }

          return 'Installation finalized';
        },
      },
    ]);

    return { customFiles: restoredCustomFiles, modifiedFiles: restoredModifiedFiles };
  }

  /**
   * Common update preparation: detect files, preserve core config, back up.
   * @param {Object} paths - InstallPaths instance
   * @param {Object} config - Clean config (may have coreConfig updated)
   * @param {Object} existingInstall - Detection result
   * @param {Object} officialModules - OfficialModules instance
   * @returns {Object} Update state: { customFiles, modifiedFiles, tempBackupDir, tempModifiedBackupDir }
   */
  async _prepareUpdateState(paths, config, existingInstall, officialModules) {
    // Detect custom and modified files BEFORE updating (compare current files vs files-manifest.csv)
    const existingFilesManifest = await this.readFilesManifest(paths.bmadDir);
    const { customFiles, modifiedFiles } = await this.detectCustomFiles(paths.bmadDir, existingFilesManifest);

    // Preserve existing core configuration during updates
    // (no-op for quick-update which already has core config from collectModuleConfigQuick)
    const coreConfigPath = paths.moduleConfig('core');
    if ((await fs.pathExists(coreConfigPath)) && (!config.coreConfig || Object.keys(config.coreConfig).length === 0)) {
      try {
        const yaml = require('yaml');
        const coreConfigContent = await fs.readFile(coreConfigPath, 'utf8');
        const existingCoreConfig = yaml.parse(coreConfigContent);

        config.coreConfig = existingCoreConfig;
        officialModules.moduleConfigs.core = existingCoreConfig;
      } catch (error) {
        await prompts.log.warn(`Warning: Could not read existing core config: ${error.message}`);
      }
    }

    const backupDirs = await this._backupUserFiles(paths, customFiles, modifiedFiles);

    return {
      customFiles,
      modifiedFiles,
      tempBackupDir: backupDirs.tempBackupDir,
      tempModifiedBackupDir: backupDirs.tempModifiedBackupDir,
    };
  }

  /**
   * Back up custom and modified files to temp directories before overwriting.
   * Returns the temp directory paths (or undefined if no files to back up).
   * @param {Object} paths - InstallPaths instance
   * @param {string[]} customFiles - Absolute paths of custom (user-added) files
   * @param {Object[]} modifiedFiles - Array of { path, relativePath } for modified files
   * @returns {Object} { tempBackupDir, tempModifiedBackupDir } — undefined if no files
   */
  async _backupUserFiles(paths, customFiles, modifiedFiles) {
    let tempBackupDir;
    let tempModifiedBackupDir;

    if (customFiles.length > 0) {
      tempBackupDir = path.join(paths.projectRoot, '_bmad-custom-backup-temp');
      await fs.ensureDir(tempBackupDir);

      for (const customFile of customFiles) {
        const relativePath = path.relative(paths.bmadDir, customFile);
        const backupPath = path.join(tempBackupDir, relativePath);
        await fs.ensureDir(path.dirname(backupPath));
        await fs.copy(customFile, backupPath);
      }
    }

    if (modifiedFiles.length > 0) {
      tempModifiedBackupDir = path.join(paths.projectRoot, '_bmad-modified-backup-temp');
      await fs.ensureDir(tempModifiedBackupDir);

      for (const modifiedFile of modifiedFiles) {
        const relativePath = path.relative(paths.bmadDir, modifiedFile.path);
        const tempBackupPath = path.join(tempModifiedBackupDir, relativePath);
        await fs.ensureDir(path.dirname(tempBackupPath));
        await fs.copy(modifiedFile.path, tempBackupPath, { overwrite: true });
      }
    }

    return { tempBackupDir, tempModifiedBackupDir };
  }

  /**
   * Sync src/scripts/* → _bmad/scripts/ so shared Python scripts
   * (e.g. resolve_customization.py) are available at install time.
   * Excludes dev-only tests and Python caches so they don't ship to users.
   * Wipes the destination first so files removed or renamed in source
   * don't linger and get recorded as installed. Also seeds
   * gitignore files for personal overrides and generated render snapshots.
   */
  async _installSharedScripts(paths) {
    const srcScriptsDir = path.join(paths.srcDir, 'src', 'scripts');
    if (!(await fs.pathExists(srcScriptsDir))) {
      throw new Error(`Shared scripts source directory not found: ${srcScriptsDir}`);
    }

    await fs.remove(paths.scriptsDir);
    await fs.ensureDir(paths.scriptsDir);
    // Ship only the runtime scripts — dev-only tests and Python caches must not land in user projects.
    const isInstallable = (srcPath) => {
      const base = path.basename(srcPath);
      return base !== 'tests' && base !== '__pycache__' && base !== '.pytest_cache' && !base.endsWith('.pyc');
    };
    await fs.copy(srcScriptsDir, paths.scriptsDir, { overwrite: true, filter: isInstallable });
    await this._trackFilesRecursive(paths.scriptsDir);

    const customGitignore = path.join(paths.customDir, '.gitignore');
    if (!(await fs.pathExists(customGitignore))) {
      await fs.writeFile(customGitignore, '*.user.toml\n', 'utf8');
      this.installedFiles.add(customGitignore);
    }

    const renderDir = path.join(paths.bmadDir, 'render');
    const renderGitignore = path.join(renderDir, '.gitignore');
    if (!(await fs.pathExists(renderGitignore))) {
      await fs.ensureDir(renderDir);
      await fs.writeFile(renderGitignore, '*\n!.gitignore\n', 'utf8');
    }
    this.installedFiles.add(renderGitignore);
  }

  async _trackFilesRecursive(dir) {
    const entries = await fs.readdir(dir, { withFileTypes: true });
    for (const entry of entries) {
      const full = path.join(dir, entry.name);
      if (entry.isDirectory()) {
        await this._trackFilesRecursive(full);
      } else if (entry.isFile()) {
        this.installedFiles.add(full);
      }
    }
  }

  async _trackPreservedModuleFiles(bmadDir, preservedModules = []) {
    for (const moduleName of preservedModules) {
      const modulePath = path.join(bmadDir, moduleName);
      if (await fs.pathExists(modulePath)) {
        await this._trackFilesRecursive(modulePath);
      }
    }
  }

  /**
   * Install official (non-custom) modules.
   * @param {Object} config - Installation configuration
   * @param {Object} paths - InstallPaths instance
   * @param {string[]} officialModuleIds - Official module IDs to install
   * @param {Function} addResult - Callback to record installation results
   * @param {boolean} isQuickUpdate - Whether this is a quick update
   * @param {Object} ctx - Shared context: { message, installedModuleNames }
   */
  async _installOfficialModules(config, paths, officialModuleIds, addResult, isQuickUpdate, officialModules, ctx) {
    const { message, installedModuleNames, shimPolicy } = ctx;
    const { CustomModuleManager } = require('../modules/custom-module-manager');

    for (const moduleName of officialModuleIds) {
      if (installedModuleNames.has(moduleName)) continue;
      installedModuleNames.add(moduleName);

      message(`${isQuickUpdate ? 'Updating' : 'Installing'} ${moduleName}...`);

      const moduleConfig = officialModules.moduleConfigs[moduleName] || {};
      const installResult = await officialModules.install(
        moduleName,
        paths.bmadDir,
        (filePath) => {
          this.installedFiles.add(filePath);
        },
        {
          skipModuleInstaller: true,
          moduleConfig: moduleConfig,
          installer: this,
          silent: true,
          channelOptions: config.channelOptions,
          installShims: shimPolicy.install,
        },
      );

      // Get display name from source module.yaml and resolve the freshest version metadata we can find locally.
      const sourcePath = await officialModules.findModuleSource(moduleName, {
        silent: true,
        channelOptions: config.channelOptions,
      });
      const moduleInfo = sourcePath ? await officialModules.getModuleInfo(sourcePath, moduleName, '') : null;
      const displayName = moduleInfo?.name || moduleName;

      const resolution = officialModules.externalModuleManager.getResolution(moduleName);
      const cachedResolution = CustomModuleManager._resolutionCache.get(moduleName);
      const versionInfo = await resolveModuleVersion(moduleName, {
        moduleSourcePath: sourcePath,
        fallbackVersion: resolution?.version || cachedResolution?.version,
        marketplacePluginNames: cachedResolution?.pluginName ? [cachedResolution.pluginName] : [],
      });
      // Prefer the git tag recorded by the resolution (e.g. "v1.7.0") over
      // the on-disk package.json (which may be ahead of the released tag).
      const version = resolution?.version || versionInfo.version || '';
      addResult(displayName, 'ok', '', {
        moduleCode: moduleName,
        newVersion: version,
        newChannel: resolution?.channel || null,
        newSha: resolution?.sha || null,
      });
    }
  }

  /**
   * Read files-manifest.csv
   * @param {string} bmadDir - BMAD installation directory
   * @returns {Array} Array of file entries from files-manifest.csv
   */
  async readFilesManifest(bmadDir) {
    const filesManifestPath = path.join(bmadDir, '_config', 'files-manifest.csv');
    if (!(await fs.pathExists(filesManifestPath))) {
      return [];
    }

    try {
      const content = await fs.readFile(filesManifestPath, 'utf8');
      const lines = content.split('\n');
      const files = [];

      for (let i = 1; i < lines.length; i++) {
        // Skip header
        const line = lines[i].trim();
        if (!line) continue;

        // Parse CSV line properly handling quoted values
        const parts = [];
        let current = '';
        let inQuotes = false;

        for (const char of line) {
          if (char === '"') {
            inQuotes = !inQuotes;
          } else if (char === ',' && !inQuotes) {
            parts.push(current);
            current = '';
          } else {
            current += char;
          }
        }
        parts.push(current); // Add last part

        if (parts.length >= 4) {
          files.push({
            type: parts[0],
            name: parts[1],
            module: parts[2],
            path: parts[3],
            hash: parts[4] || null, // Hash may not exist in old manifests
          });
        }
      }

      return files;
    } catch (error) {
      await prompts.log.warn('Could not read files-manifest.csv: ' + error.message);
      return [];
    }
  }

  /**
   * Detect custom and modified files
   * @param {string} bmadDir - BMAD installation directory
   * @param {Array} existingFilesManifest - Previous files from files-manifest.csv
   * @returns {Object} Object with customFiles and modifiedFiles arrays
   */
  async detectCustomFiles(bmadDir, existingFilesManifest) {
    const customFiles = [];
    const modifiedFiles = [];

    // Memory subtrees (v6.1: _bmad/_memory, current: _bmad/memory) hold
    // per-user runtime data generated by agents with sidecars. These files
    // aren't installer-managed and must never be reported as "custom" or
    // "modified" — they're user state, not user overrides.
    const bmadMemoryPaths = ['_memory', 'memory'];

    // Check if the manifest has hashes - if not, we can't detect modifications
    let manifestHasHashes = false;
    if (existingFilesManifest && existingFilesManifest.length > 0) {
      manifestHasHashes = existingFilesManifest.some((f) => f.hash);
    }

    // Build map of previously installed files from files-manifest.csv with their hashes
    const installedFilesMap = new Map();
    for (const fileEntry of existingFilesManifest) {
      if (fileEntry.path) {
        const absolutePath = path.join(bmadDir, fileEntry.path);
        installedFilesMap.set(path.normalize(absolutePath), {
          hash: fileEntry.hash,
          relativePath: fileEntry.path,
        });
      }
    }

    // Recursively scan bmadDir for all files
    const scanDirectory = async (dir) => {
      try {
        const entries = await fs.readdir(dir, { withFileTypes: true });
        for (const entry of entries) {
          const fullPath = path.join(dir, entry.name);

          if (entry.isDirectory()) {
            const relativeDir = path.relative(bmadDir, fullPath);
            // Render snapshots are generated state, not user-authored customization.
            if (entry.name === 'node_modules' || entry.name === '.git' || relativeDir === 'render') {
              continue;
            }
            await scanDirectory(fullPath);
          } else if (entry.isFile()) {
            const normalizedPath = path.normalize(fullPath);
            const fileInfo = installedFilesMap.get(normalizedPath);

            // Skip certain system files that are auto-generated
            const relativePath = path.relative(bmadDir, fullPath);
            const fileName = path.basename(fullPath);

            // Skip _config directory EXCEPT for modified agent customizations
            if (relativePath.startsWith('_config/') || relativePath.startsWith('_config\\')) {
              // Special handling for .customize.yaml files - only preserve if modified
              if (relativePath.includes('/agents/') && fileName.endsWith('.customize.yaml')) {
                // Check if the customization file has been modified from manifest
                const manifestPath = path.join(bmadDir, '_config', 'manifest.yaml');
                if (await fs.pathExists(manifestPath)) {
                  const crypto = require('node:crypto');
                  const currentContent = await fs.readFile(fullPath, 'utf8');
                  const currentHash = crypto.createHash('sha256').update(currentContent).digest('hex');

                  const yaml = require('yaml');
                  const manifestContent = await fs.readFile(manifestPath, 'utf8');
                  const manifestData = yaml.parse(manifestContent);
                  const originalHash = manifestData.agentCustomizations?.[relativePath];

                  // Only add to customFiles if hash differs (user modified)
                  if (originalHash && currentHash !== originalHash) {
                    customFiles.push(fullPath);
                  }
                }
              }
              continue;
            }

            if (bmadMemoryPaths.some((mp) => relativePath === mp || relativePath.startsWith(mp + '/'))) {
              continue;
            }

            // Skip config.yaml files - these are regenerated on each install/update
            if (fileName === 'config.yaml') {
              continue;
            }

            if (!fileInfo) {
              // File not in manifest = custom file
              // EXCEPT: Agent .md files in module folders are generated files, not custom
              // Only treat .md files under _config/agents/ as custom
              if (!(fileName.endsWith('.md') && relativePath.includes('/agents/') && !relativePath.startsWith('_config/'))) {
                customFiles.push(fullPath);
              }
            } else if (manifestHasHashes && fileInfo.hash) {
              // File in manifest with hash - check if it was modified
              const currentHash = await this.manifest.calculateFileHash(fullPath);
              if (currentHash && currentHash !== fileInfo.hash) {
                // Hash changed = file was modified
                modifiedFiles.push({
                  path: fullPath,
                  relativePath: fileInfo.relativePath,
                });
              }
            }
          }
        }
      } catch {
        // Ignore errors scanning directories
      }
    };

    await scanDirectory(bmadDir);
    return { customFiles, modifiedFiles };
  }

  /**
   * Generate clean config.yaml files for each installed module
   * @param {string} bmadDir - BMAD installation directory
   * @param {Object} moduleConfigs - Collected configuration values
   */
  async generateModuleConfigs(bmadDir, moduleConfigs) {
    const yaml = require('yaml');

    // Extract core config values to share with other modules
    const coreConfig = moduleConfigs.core || {};

    // Get all installed module directories
    const entries = await fs.readdir(bmadDir, { withFileTypes: true });
    const nonModuleDirs = new Set(['_config', '_memory', 'memory', 'docs', 'scripts', 'custom', 'render']);
    const installedModules = entries.filter((entry) => entry.isDirectory() && !nonModuleDirs.has(entry.name)).map((entry) => entry.name);

    // Generate config.yaml for each installed module
    for (const moduleName of installedModules) {
      const modulePath = path.join(bmadDir, moduleName);

      // Get module-specific config or use empty object if none
      const config = moduleConfigs[moduleName] || {};

      if (await fs.pathExists(modulePath)) {
        const configPath = path.join(modulePath, 'config.yaml');

        // Create header
        const packageJson = require(path.join(getProjectRoot(), 'package.json'));
        const header = `# ${moduleName.toUpperCase()} Module Configuration
# Generated by BMAD installer
# Version: ${packageJson.version}
# Date: ${new Date().toISOString()}

`;

        // For non-core modules, add core config values directly
        let finalConfig = { ...config };
        let coreSection = '';

        if (moduleName !== 'core' && coreConfig && Object.keys(coreConfig).length > 0) {
          // Add core values directly to the module config
          // These will be available for reference in the module
          finalConfig = {
            ...config,
            ...coreConfig, // Spread core config values directly into the module config
          };

          // Create a comment section to identify core values
          coreSection = '\n# Core Configuration Values\n';
        }

        // Clean the config to remove any non-serializable values (like functions)
        const cleanConfig = structuredClone(finalConfig);

        // Convert config to YAML
        let yamlContent = yaml.stringify(cleanConfig, {
          indent: 2,
          lineWidth: 0,
          minContentWidth: 0,
        });

        // If we have core values, reorganize the YAML to group them with their comment
        if (coreSection && moduleName !== 'core') {
          // Split the YAML into lines
          const lines = yamlContent.split('\n');
          const moduleConfigLines = [];
          const coreConfigLines = [];

          // Separate module-specific and core config lines
          for (const line of lines) {
            const key = line.split(':')[0].trim();
            if (Object.prototype.hasOwnProperty.call(coreConfig, key)) {
              coreConfigLines.push(line);
            } else {
              moduleConfigLines.push(line);
            }
          }

          // Rebuild YAML with module config first, then core config with comment
          yamlContent = moduleConfigLines.join('\n');
          if (coreConfigLines.length > 0) {
            yamlContent += coreSection + coreConfigLines.join('\n');
          }
        }

        // Write the clean config file with POSIX-compliant final newline
        const content = header + yamlContent;
        await fs.writeFile(configPath, content.endsWith('\n') ? content : content + '\n', 'utf8');

        // Track the config file in installedFiles
        this.installedFiles.add(configPath);
      }
    }
  }

  /**
   * Merge all module-help.csv files into a single bmad-help.csv.
   * Scans all installed modules for module-help.csv and merges them.
   * Output preserves the source schema verbatim — see schema below.
   * @param {string} bmadDir - BMAD installation directory
   * @param {Array<Object>} _agentEntries - Unused; retained for call-site compatibility
   */
  async mergeModuleHelpCatalogs(bmadDir, _agentEntries = []) {
    const allRows = [];
    const headerRow = MODULE_HELP_CSV_HEADER;
    const COLUMN_COUNT = 13;
    const PHASE_INDEX = 7;

    // Get all installed module directories
    const entries = await fs.readdir(bmadDir, { withFileTypes: true });
    const nonModuleDirs = new Set(['_config', '_memory', 'memory', 'docs', 'scripts', 'custom', 'render']);
    const installedModules = entries.filter((entry) => entry.isDirectory() && !nonModuleDirs.has(entry.name)).map((entry) => entry.name);

    // Add core module to scan (it's installed at root level as _config, but we check src/core-skills)
    const coreModulePath = getSourcePath('core-skills');
    const modulePaths = new Map();

    // Map all module source paths
    if (await fs.pathExists(coreModulePath)) {
      modulePaths.set('core', coreModulePath);
    }

    // Map installed module paths
    for (const moduleName of installedModules) {
      const modulePath = path.join(bmadDir, moduleName);
      modulePaths.set(moduleName, modulePath);
    }

    // Scan each module for module-help.csv
    for (const [moduleName, modulePath] of modulePaths) {
      const helpFilePath = path.join(modulePath, 'module-help.csv');

      if (await fs.pathExists(helpFilePath)) {
        try {
          const content = await fs.readFile(helpFilePath, 'utf8');
          const lines = content.split('\n').filter((line) => line.trim() && !line.startsWith('#'));

          let headerWarned = false;
          for (const line of lines) {
            // Header row: warn on drift from canonical schema, then skip.
            // Data rows are loaded positionally regardless, so the warning
            // is advisory — the maintainer should rename their columns.
            if (line.startsWith('module,')) {
              if (!headerWarned && line.trim() !== headerRow) {
                await prompts.log.warn(
                  `  ${moduleName}/module-help.csv header does not match canonical schema. ` +
                    `Expected: ${headerRow} | Found: ${line.trim()} | Data loaded positionally.`,
                );
                headerWarned = true;
              }
              continue;
            }

            // Parse the line - handle quoted fields with commas
            const columns = this.parseCSVLine(line);
            if (columns.length < COLUMN_COUNT - 1) continue;

            // Pad short rows; truncate over-long rows
            const padded = columns.slice(0, COLUMN_COUNT);
            while (padded.length < COLUMN_COUNT) padded.push('');

            // If module column is empty, fill with this module's name
            // (core stays empty so its rows render as universal tools)
            if ((!padded[0] || padded[0].trim() === '') && moduleName !== 'core') {
              padded[0] = moduleName;
            }

            allRows.push(padded.map((c) => this.escapeCSVField(c)).join(','));
          }

          if (process.env.BMAD_VERBOSE_INSTALL === 'true') {
            await prompts.log.message(`  Merged module-help from: ${moduleName}`);
          }
        } catch (error) {
          await prompts.log.warn(`  Warning: Failed to read module-help.csv from ${moduleName}: ${error.message}`);
        }
      }
    }

    // Sort by module, then phase. Stable sort preserves authored order within a phase.
    const decorated = allRows.map((row, index) => ({ row, index, cols: this.parseCSVLine(row) }));
    decorated.sort((a, b) => {
      const moduleA = (a.cols[0] || '').toLowerCase();
      const moduleB = (b.cols[0] || '').toLowerCase();
      if (moduleA !== moduleB) return moduleA.localeCompare(moduleB);

      const phaseA = a.cols[PHASE_INDEX] || '';
      const phaseB = b.cols[PHASE_INDEX] || '';
      if (phaseA !== phaseB) return phaseA.localeCompare(phaseB);

      return a.index - b.index;
    });
    const sortedRows = decorated.map((d) => d.row);

    // Write merged catalog
    const outputDir = path.join(bmadDir, '_config');
    await fs.ensureDir(outputDir);
    const outputPath = path.join(outputDir, 'bmad-help.csv');

    const mergedContent = [headerRow, ...sortedRows].join('\n');
    await fs.writeFile(outputPath, mergedContent, 'utf8');

    // Track the installed file
    this.installedFiles.add(outputPath);

    if (process.env.BMAD_VERBOSE_INSTALL === 'true') {
      await prompts.log.message(`  Generated bmad-help.csv: ${sortedRows.length} workflows`);
    }
  }

  /**
   * Render a consolidated install summary using prompts.note()
   * @param {Array} results - Array of {step, status: 'ok'|'error'|'warn', detail}
   * @param {Object} context - {bmadDir, modules, ides, customFiles, modifiedFiles}
   */
  async renderInstallSummary(results, context = {}) {
    const color = await prompts.getColor();
    const selectedIdes = new Set((context.ides || []).map((ide) => String(ide).toLowerCase()));

    // Build step lines with status indicators
    const preVersions = context.preInstallVersions || new Map();
    const lines = [];
    for (const r of results) {
      const stepLabel = r.step;

      let icon;
      if (r.status === 'ok') {
        icon = color.green('\u2713');
      } else if (r.status === 'warn') {
        icon = color.yellow('!');
      } else {
        icon = color.red('\u2717');
      }

      // Build version detail for module results
      let detail = '';
      if (r.moduleCode && r.newVersion) {
        const oldVersion = preVersions.get(r.moduleCode);
        // Format a version label for display:
        //   "main" → "main @ <short-sha>" (next channel shows what SHA landed)
        //   "v1.7.0" or "1.7.0" → "v1.7.0" (prefix 'v' when missing)
        //   anything else (legacy strings) → as-is
        const fmt = (v, sha) => {
          if (typeof v !== 'string' || !v) return '';
          if (v === 'main' || v === 'HEAD') return sha ? `main @ ${sha.slice(0, 7)}` : 'main';
          if (/^v?\d+\.\d+\.\d+/.test(v)) return v.startsWith('v') ? v : `v${v}`;
          return v;
        };
        const newV = fmt(r.newVersion, r.newSha);
        // 'main'/'HEAD' strings only identify the channel, not the commit, so
        // we can't assert "no change" without comparing SHAs — and preVersions
        // doesn't carry the old SHA. Render these as a refresh instead of a
        // false-negative "no change".
        const isMainLike = oldVersion === 'main' || oldVersion === 'HEAD';
        if (oldVersion && oldVersion === r.newVersion && !isMainLike) {
          detail = ` (${newV}, no change)`;
        } else if (oldVersion && isMainLike) {
          detail = ` (${newV}, refreshed)`;
        } else if (oldVersion) {
          detail = ` (${fmt(oldVersion, r.newSha)} → ${newV})`;
        } else {
          detail = ` (${newV}, installed)`;
        }
      } else if (r.detail) {
        detail = ` (${r.detail})`;
      }
      lines.push(`  ${icon}  ${stepLabel}${detail}`);
    }

    if ((context.ides || []).length === 0) {
      lines.push(`  ${color.green('\u2713')}  No IDE selected (installed in _bmad only)`);
    }

    // Context and warnings
    lines.push('');
    if (context.bmadDir) {
      lines.push(`  Installed to: ${context.bmadDir}`);
    }
    if (context.customFiles && context.customFiles.length > 0) {
      lines.push(`  ${color.cyan(`Custom files preserved: ${context.customFiles.length}`)}`);
    }
    if (context.modifiedFiles && context.modifiedFiles.length > 0) {
      lines.push(`  ${color.yellow(`Modified files backed up (.bak): ${context.modifiedFiles.length}`)}`);
    }
    if (context.shimStatus?.retained > 0) {
      lines.push(`  ${color.yellow(`Deprecated shim skills retained: ${context.shimStatus.retained}`)} (re-run to remove them)`);
    }
    if (context.shimStatus?.removed > 0) {
      lines.push(`  ${color.green(`Deprecated shim skills removed: ${context.shimStatus.removed}`)}`);
    }

    // Next steps
    lines.push(
      '',
      '  Get started:',
      `    1. Launch your AI agent from your project folder`,
      `    2. Not sure what to do? Invoke the ${color.cyan('bmad-help')} skill and ask it what to do!`,
    );

    // Repeat the uv warning here when it applies. The pre-install probe fires
    // before every prompt in the run, so by now it is far up the scrollback —
    // and this box is titled "BMAD is ready to use!", which is only true if
    // the rendered skills can actually start.
    const { detectUv } = require('./uv-check');
    if (!detectUv()) {
      lines.push(
        '',
        `    ${color.yellow('⚠ uv is not installed.')} ${color.cyan('bmad-build')} and ${color.cyan('bmad-build-auto')} render through`,
        `    ${color.cyan('uv run')} and will halt on activation until you set it up — ask your agent to`,
        `    "install and set up uv for me", or see https://docs.astral.sh/uv/`,
      );
    }

    lines.push(
      '',
      `    Blog, Docs and Guides: ${color.blue('https://bmadcode.com/')}`,
      `    Community: ${color.blue('https://discord.gg/gk8jAdXWmj')}`,
    );

    await prompts.box(lines.join('\n'), 'BMAD is ready to use!', {
      rounded: true,
      formatBorder: color.green,
    });
  }

  /**
   * Display registry-defined post-install messages for the modules installed in
   * this run. These are "action needed" notices (e.g. "run the bmad-loop-setup
   * skill") that the user must see to finish setup. They are defined via the
   * `post-install-message` property on a module's bmad-modules.yaml entry.
   *
   * Interactive installs require the user to acknowledge each message (press
   * Enter); non-interactive (--yes / skipPrompts) installs print the message
   * and continue without blocking, so CI/scripted installs don't hang.
   *
   * @param {Object} config - Install config (config.modules, config.skipPrompts)
   * @param {Object} officialModules - OfficialModules instance (carries the registry)
   */
  async _displayPostInstallMessages(config, officialModules) {
    const moduleCodes = config.modules || [];
    if (moduleCodes.length === 0) return;

    const externalManager = officialModules.externalModuleManager;
    if (!externalManager) return;

    const color = await prompts.getColor();

    for (const code of moduleCodes) {
      let moduleInfo;
      try {
        moduleInfo = await externalManager.getModuleByCode(code);
      } catch {
        continue; // Built-in modules (core/bmm) aren't in the registry — skip.
      }

      const message = moduleInfo && moduleInfo.postInstallMessage;
      if (!message) continue;

      await prompts.box(String(message).trim(), `⚑ Action needed — ${moduleInfo.name || code}`, {
        rounded: true,
        formatBorder: color.yellow,
      });

      // Interactive: require the user to acknowledge before continuing. Skip the
      // blocking prompt in non-interactive installs (the message is still shown).
      if (!config.skipPrompts) {
        await prompts.text({
          message: 'Press Enter to acknowledge',
          placeholder: '',
          default: '',
        });
      }
    }
  }

  /**
   * Quick update method - preserves all settings and only prompts for new config fields
   * @param {Object} config - Configuration with directory
   * @returns {Object} Update result
   */
  async quickUpdate(config) {
    const projectDir = path.resolve(config.directory);
    const { bmadDir } = await this.findBmadDir(projectDir);

    // Check if bmad directory exists
    if (!(await fs.pathExists(bmadDir))) {
      throw new Error(`BMAD not installed at ${bmadDir}. Use regular install for first-time setup.`);
    }

    // Detect existing installation
    const existingInstall = await ExistingInstall.detect(bmadDir);
    const configuredIdes = existingInstall.ides;
    const projectRoot = path.dirname(bmadDir);

    // Resolve any legacy/aliased module codes (e.g. an install recorded as
    // `bauto` before the registry renamed it to `bmad-loop`) to their current
    // canonical code up front. Without this, a renamed module's old installs
    // would fall out of `availableModuleIds` below and get silently frozen
    // (see the `baut` → `automator` incident in CHANGELOG v6.7.1) instead of
    // migrating forward.
    const aliasMigrations = [];
    const seenModuleIds = new Set();
    const installedModules = [];
    for (const rawId of existingInstall.moduleIds) {
      const canonicalId = await this.externalModuleManager.resolveCanonicalCode(rawId);
      if (canonicalId !== rawId) {
        aliasMigrations.push({ from: rawId, to: canonicalId });
      }
      if (!seenModuleIds.has(canonicalId)) {
        seenModuleIds.add(canonicalId);
        installedModules.push(canonicalId);
      }
    }
    for (const { from, to } of aliasMigrations) {
      await prompts.log.info(`Migrating installed module '${from}' to its renamed successor '${to}'.`);
    }

    // Get available modules (what we have source for)
    const availableModulesData = await new OfficialModules().listAvailable();
    const availableModules = [...availableModulesData.modules];

    // Add external official modules to available modules
    const externalModules = await this.externalModuleManager.listAvailable();
    for (const externalModule of externalModules) {
      if (installedModules.includes(externalModule.code) && !availableModules.some((m) => m.id === externalModule.code)) {
        availableModules.push({
          id: externalModule.code,
          name: externalModule.name,
          isExternal: true,
          fromExternal: true,
        });
      }
    }

    // Add installed custom modules to available modules
    const { CustomModuleManager } = require('../modules/custom-module-manager');
    const customMgr = new CustomModuleManager();
    for (const moduleId of installedModules) {
      if (!availableModules.some((m) => m.id === moduleId)) {
        const customSource = await customMgr.findModuleSourceByCode(moduleId, { bmadDir });
        if (customSource) {
          availableModules.push({
            id: moduleId,
            name: moduleId,
            isExternal: true,
            fromCustom: true,
          });
        }
      }
    }

    const availableModuleIds = new Set(availableModules.map((m) => m.id));

    // Only update modules that are BOTH installed AND available (we have source for)
    const modulesToUpdate = installedModules.filter((id) => availableModuleIds.has(id));
    const skippedModules = installedModules.filter((id) => !availableModuleIds.has(id));

    if (skippedModules.length > 0) {
      await prompts.log.warn(`Skipping ${skippedModules.length} module(s) - no source available: ${skippedModules.join(', ')}`);
    }

    // Build channel options from the existing manifest FIRST so the config
    // collector below (which triggers external-module clones via
    // findModuleSource) knows each module's recorded channel and doesn't
    // silently redecide it. Without this, modules previously on 'next' or
    // 'pinned' would trigger a stable-channel tag lookup at config-collection
    // time, burning GitHub API quota and potentially failing.
    const manifestData = await this.manifest.read(bmadDir);
    const channelOptions = { global: null, nextSet: new Set(), pins: new Map(), warnings: [] };
    if (manifestData?.modulesDetailed) {
      const { fetchStableTags, classifyUpgrade, parseGitHubRepo } = require('../modules/channel-resolver');
      for (const entry of manifestData.modulesDetailed) {
        if (!entry?.name || !entry?.channel) continue;
        if (entry.channel === 'pinned' && entry.version) {
          channelOptions.pins.set(entry.name, entry.version);
          continue;
        }
        if (entry.channel === 'next') {
          channelOptions.nextSet.add(entry.name);
          continue;
        }
        // Stable: classify the available upgrade. Patches and minors fall
        // through (stable default picks up the top tag). A major upgrade
        // requires opt-in, so under quick-update's non-interactive semantics
        // we pin to the current version to prevent a silent breaking jump.
        if (entry.channel === 'stable' && entry.version && entry.repoUrl) {
          const parsed = parseGitHubRepo(entry.repoUrl);
          if (!parsed) continue;
          try {
            const tags = await fetchStableTags(parsed.owner, parsed.repo);
            if (tags.length === 0) continue;
            const topTag = tags[0].tag;
            const cls = classifyUpgrade(entry.version, topTag);
            if (cls === 'major') {
              channelOptions.pins.set(entry.name, entry.version);
              await prompts.log.warn(
                `${entry.name} ${entry.version} → ${topTag} is a new major release; staying on ${entry.version}. ` +
                  `Run \`bmad install\` (Modify) with \`--pin ${entry.name}=${topTag}\` to accept.`,
              );
            }
          } catch (error) {
            // Tag lookup failed (offline, rate-limited). Stay on the current
            // version rather than guessing — the existing cache is already
            // at that ref, so re-using it keeps the install stable.
            channelOptions.pins.set(entry.name, entry.version);
            await prompts.log.warn(`Could not check ${entry.name} for updates (${error.message}); staying on ${entry.version}.`);
          }
        }
      }
    }

    // Load existing configs and collect new fields (if any)
    await prompts.log.info('Checking for new configuration options...');
    const quickModules = new OfficialModules({ channelOptions });
    await quickModules.loadExistingConfig(projectDir);

    let promptedForNewFields = false;

    const corePrompted = await quickModules.collectModuleConfigQuick('core', projectDir, true);
    if (corePrompted) {
      promptedForNewFields = true;
    }

    for (const moduleName of modulesToUpdate) {
      if (moduleName === 'core') continue; // Already collected above
      const modulePrompted = await quickModules.collectModuleConfigQuick(moduleName, projectDir, true);
      if (modulePrompted) {
        promptedForNewFields = true;
      }
    }

    if (!promptedForNewFields) {
      await prompts.log.success('All configuration is up to date, no new options to configure');
    }

    quickModules.collectedConfig._meta = {
      version: require(path.join(getProjectRoot(), 'package.json')).version,
      installDate: new Date().toISOString(),
      lastModified: new Date().toISOString(),
    };

    // Build config and delegate to install()
    const installConfig = {
      directory: projectDir,
      modules: modulesToUpdate,
      ides: configuredIdes,
      coreConfig: quickModules.collectedConfig.core,
      moduleConfigs: quickModules.collectedConfig,
      // Forward `--set` overrides so the post-install patch step
      // (`applySetOverrides`) runs at the end of quick-update too. The
      // installer.install path applies them after writeCentralConfig.
      setOverrides: config.setOverrides || {},
      installShims: config.installShims,
      actionType: 'install',
      _quickUpdate: true,
      _preserveModules: skippedModules,
      _existingModules: installedModules,
      channelOptions,
    };

    await this.install(installConfig);

    // Now that the canonical module has been installed successfully, remove
    // the stale directory left behind under its old code so the two don't
    // coexist (e.g. `_bmad/bauto/` once `_bmad/bmad-loop/` is in place).
    for (const { from, to } of aliasMigrations) {
      if (!modulesToUpdate.includes(to)) continue; // new code wasn't actually installed this run
      const oldModuleDir = path.join(bmadDir, from);
      if (await fs.pathExists(oldModuleDir)) {
        await fs.remove(oldModuleDir);
        await prompts.log.success(`Removed legacy '${from}' directory after migrating to '${to}'.`);
      }
    }

    return {
      success: true,
      moduleCount: modulesToUpdate.length,
      hadNewFields: promptedForNewFields,
      modules: modulesToUpdate,
      skippedModules: skippedModules,
      ides: configuredIdes,
    };
  }

  /**
   * Uninstall BMAD with selective removal options
   * @param {string} directory - Project directory
   * @param {Object} options - Uninstall options
   * @param {boolean} [options.removeModules=true] - Remove _bmad/ directory
   * @param {boolean} [options.removeIdeConfigs=true] - Remove IDE configurations
   * @param {boolean} [options.removeOutputFolder=false] - Remove user artifacts output folder
   * @returns {Object} Result with success status and removed components
   */
  async uninstall(directory, options = {}) {
    const projectDir = path.resolve(directory);
    const { bmadDir } = await this.findBmadDir(projectDir);

    if (!(await fs.pathExists(bmadDir))) {
      return { success: false, reason: 'not-installed' };
    }

    // 1. DETECT: Read state BEFORE deleting anything
    const existingInstall = await ExistingInstall.detect(bmadDir);
    const outputFolder = await this._readOutputFolder(bmadDir);

    const removed = { modules: false, ideConfigs: false, outputFolder: false };

    // 2. IDE CLEANUP (before _bmad/ deletion so configs are accessible)
    if (options.removeIdeConfigs !== false) {
      await this.uninstallIdeConfigs(projectDir, existingInstall, { silent: options.silent });
      removed.ideConfigs = true;
    }

    // 3. OUTPUT FOLDER (only if explicitly requested)
    if (options.removeOutputFolder === true && outputFolder) {
      removed.outputFolder = await this.uninstallOutputFolder(projectDir, outputFolder);
    }

    // 4. BMAD DIRECTORY (last, after everything that needs it)
    if (options.removeModules !== false) {
      removed.modules = await this.uninstallModules(projectDir);
    }

    return { success: true, removed, version: existingInstall.installed ? existingInstall.version : null };
  }

  /**
   * Uninstall IDE configurations only
   * @param {string} projectDir - Project directory
   * @param {Object} existingInstall - Detection result from detector.detect()
   * @param {Object} [options] - Options (e.g. { silent: true })
   * @returns {Promise<Object>} Results from IDE cleanup
   */
  async uninstallIdeConfigs(projectDir, existingInstall, options = {}) {
    await this.ideManager.ensureInitialized();
    const cleanupOptions = { isUninstall: true, silent: options.silent };
    const ideList = existingInstall.ides;
    if (ideList.length > 0) {
      return this.ideManager.cleanupByList(projectDir, ideList, cleanupOptions);
    }
    return this.ideManager.cleanup(projectDir, cleanupOptions);
  }

  /**
   * Remove user artifacts output folder
   * @param {string} projectDir - Project directory
   * @param {string} outputFolder - Output folder name (relative)
   * @returns {Promise<boolean>} Whether the folder was removed
   */
  async uninstallOutputFolder(projectDir, outputFolder) {
    if (!outputFolder) return false;
    const resolvedProject = path.resolve(projectDir);
    const outputPath = path.resolve(resolvedProject, outputFolder);
    if (!outputPath.startsWith(resolvedProject + path.sep)) {
      return false;
    }
    if (await fs.pathExists(outputPath)) {
      await fs.remove(outputPath);
      return true;
    }
    return false;
  }

  /**
   * Remove the _bmad/ directory
   * @param {string} projectDir - Project directory
   * @returns {Promise<boolean>} Whether the directory was removed
   */
  async uninstallModules(projectDir) {
    const { bmadDir } = await this.findBmadDir(projectDir);
    if (await fs.pathExists(bmadDir)) {
      await fs.remove(bmadDir);
      return true;
    }
    return false;
  }

  /**
   * Get installation status
   */
  async getStatus(directory) {
    const projectDir = path.resolve(directory);
    const { bmadDir } = await this.findBmadDir(projectDir);
    return await ExistingInstall.detect(bmadDir);
  }

  /**
   * Get available modules
   */
  async getAvailableModules() {
    return await new OfficialModules().listAvailable();
  }

  /**
   * Get the configured output folder name for a project
   * Resolves bmadDir internally from projectDir
   * @param {string} projectDir - Project directory
   * @returns {string} Output folder name (relative, default: '_bmad-output')
   */
  async getOutputFolder(projectDir) {
    const { bmadDir } = await this.findBmadDir(projectDir);
    return this._readOutputFolder(bmadDir);
  }

  /**
   * Find the bmad installation directory in a project
   * Always uses the standard _bmad folder name
   * @param {string} projectDir - Project directory
   * @returns {Promise<Object>} { bmadDir: string }
   */
  async findBmadDir(projectDir) {
    const bmadDir = path.join(projectDir, BMAD_FOLDER_NAME);
    return { bmadDir };
  }

  /**
   * Read the output_folder setting from module config files
   * Checks bmm/config.yaml first, then other module configs
   * @param {string} bmadDir - BMAD installation directory
   * @returns {string} Output folder path or default
   */
  async _readOutputFolder(bmadDir) {
    const yaml = require('yaml');

    // Check bmm/config.yaml first (most common)
    const bmmConfigPath = path.join(bmadDir, 'bmm', 'config.yaml');
    if (await fs.pathExists(bmmConfigPath)) {
      try {
        const content = await fs.readFile(bmmConfigPath, 'utf8');
        const config = yaml.parse(content);
        if (config && config.output_folder) {
          // Strip {project-root}/ prefix if present
          return config.output_folder.replace(/^\{project-root\}[/\\]/, '');
        }
      } catch {
        // Fall through to other modules
      }
    }

    // Scan other module config.yaml files
    try {
      const entries = await fs.readdir(bmadDir, { withFileTypes: true });
      for (const entry of entries) {
        if (!entry.isDirectory() || entry.name === 'bmm' || entry.name.startsWith('_')) continue;
        const configPath = path.join(bmadDir, entry.name, 'config.yaml');
        if (await fs.pathExists(configPath)) {
          try {
            const content = await fs.readFile(configPath, 'utf8');
            const config = yaml.parse(content);
            if (config && config.output_folder) {
              return config.output_folder.replace(/^\{project-root\}[/\\]/, '');
            }
          } catch {
            // Continue scanning
          }
        }
      }
    } catch {
      // Directory scan failed
    }

    // Default fallback
    return '_bmad-output';
  }

  /**
   * Parse a CSV line, handling quoted fields
   * @param {string} line - CSV line to parse
   * @returns {Array} Array of field values
   */
  parseCSVLine(line) {
    const result = [];
    let current = '';
    let inQuotes = false;

    for (let i = 0; i < line.length; i++) {
      const char = line[i];
      const nextChar = line[i + 1];

      if (char === '"') {
        if (inQuotes && nextChar === '"') {
          // Escaped quote
          current += '"';
          i++; // Skip next quote
        } else {
          // Toggle quote mode
          inQuotes = !inQuotes;
        }
      } else if (char === ',' && !inQuotes) {
        result.push(current);
        current = '';
      } else {
        current += char;
      }
    }
    result.push(current);
    return result;
  }

  /**
   * Escape a CSV field if it contains special characters
   * @param {string} field - Field value to escape
   * @returns {string} Escaped field
   */
  escapeCSVField(field) {
    if (field === null || field === undefined) {
      return '';
    }
    const str = String(field);
    // If field contains comma, quote, or newline, wrap in quotes and escape inner quotes
    if (str.includes(',') || str.includes('"') || str.includes('\n')) {
      return `"${str.replaceAll('"', '""')}"`;
    }
    return str;
  }
}

module.exports = { Installer };

const path = require('node:path');
const fs = require('../fs-native');
const yaml = require('yaml');
const prompts = require('../prompts');
const { getProjectRoot, getSourcePath, getModulePath } = require('../project-root');
const { CLIUtils } = require('../cli-utils');
const { ExternalModuleManager } = require('./external-manager');
const { discoverShims } = require('../core/shim-policy');

class OfficialModules {
  constructor(options = {}) {
    this.externalModuleManager = new ExternalModuleManager();
    // Config collection state (merged from ConfigCollector)
    this.collectedConfig = {};
    this._existingConfig = null;
    // Tracked during interactive config collection so {directory_name}
    // placeholder defaults can be resolved in buildQuestion().
    this.currentProjectDir = null;
    // Install-time channel flag state. Set by Config.build once, then used as
    // the default for every findModuleSource/cloneExternalModule call so that
    // pre-install config collection and the install step agree on which ref
    // to clone.
    this.channelOptions = options.channelOptions || null;
  }

  /**
   * Module configurations collected during install.
   */
  get moduleConfigs() {
    return this.collectedConfig;
  }

  /**
   * Existing module configurations read from a previous installation.
   */
  get existingConfig() {
    return this._existingConfig;
  }

  /**
   * Build a configured OfficialModules instance from install config.
   * @param {Object} config - Clean install config (from Config.build)
   * @param {Object} paths - InstallPaths instance
   * @returns {OfficialModules}
   */
  static async build(config, paths) {
    const instance = new OfficialModules({ channelOptions: config.channelOptions });

    // Pre-collected by UI or quickUpdate — store and load existing for path-change detection
    if (config.moduleConfigs) {
      instance.collectedConfig = config.moduleConfigs;
      await instance.loadExistingConfig(paths.projectRoot);
      return instance;
    }

    // Headless collection (--yes flag from CLI without UI, tests)
    if (config.hasCoreConfig()) {
      instance.collectedConfig.core = config.coreConfig;
      instance.allAnswers = {};
      for (const [key, value] of Object.entries(config.coreConfig)) {
        instance.allAnswers[`core_${key}`] = value;
      }
    }

    const toCollect = config.hasCoreConfig() ? config.modules.filter((m) => m !== 'core') : [...config.modules];

    await instance.collectAllConfigurations(toCollect, paths.projectRoot, {
      skipPrompts: config.skipPrompts,
    });

    return instance;
  }

  /**
   * Copy a file to the target location
   * @param {string} sourcePath - Source file path
   * @param {string} targetPath - Target file path
   * @param {boolean} overwrite - Whether to overwrite existing files (default: true)
   */
  async copyFile(sourcePath, targetPath, overwrite = true) {
    await fs.copy(sourcePath, targetPath, { overwrite });
  }

  /**
   * Copy a directory recursively
   * @param {string} sourceDir - Source directory path
   * @param {string} targetDir - Target directory path
   * @param {boolean} overwrite - Whether to overwrite existing files (default: true)
   */
  async copyDirectory(sourceDir, targetDir, overwrite = true) {
    await fs.ensureDir(targetDir);
    const entries = await fs.readdir(sourceDir, { withFileTypes: true });

    for (const entry of entries) {
      const sourcePath = path.join(sourceDir, entry.name);
      const targetPath = path.join(targetDir, entry.name);

      if (entry.isDirectory()) {
        await this.copyDirectory(sourcePath, targetPath, overwrite);
      } else {
        await this.copyFile(sourcePath, targetPath, overwrite);
      }
    }
  }

  /**
   * List all available built-in modules (core and bmm).
   * All other modules come from external-official-modules.yaml
   * @returns {Object} Object with modules array
   */
  async listAvailable() {
    const modules = [];

    // Add built-in core module (directly under src/core-skills)
    const corePath = getSourcePath('core-skills');
    if (await fs.pathExists(corePath)) {
      const coreInfo = await this.getModuleInfo(corePath, 'core', 'src/core-skills');
      if (coreInfo) {
        modules.push(coreInfo);
      }
    }

    // Add built-in bmm module (directly under src/bmm-skills)
    const bmmPath = getSourcePath('bmm-skills');
    if (await fs.pathExists(bmmPath)) {
      const bmmInfo = await this.getModuleInfo(bmmPath, 'bmm', 'src/bmm-skills');
      if (bmmInfo) {
        modules.push(bmmInfo);
      }
    }

    return { modules };
  }

  async discoverShims(moduleNames = [], options = {}) {
    const shims = [];

    for (const moduleName of moduleNames) {
      const sourcePath = await this.findModuleSource(moduleName, {
        silent: true,
        channelOptions: options.channelOptions,
      });
      if (!sourcePath) continue;

      const moduleShims = await discoverShims(sourcePath);
      for (const shim of moduleShims) shims.push({ ...shim, module: moduleName });
    }

    return shims;
  }

  /**
   * Get module information from a module path
   * @param {string} modulePath - Path to the module directory
   * @param {string} defaultName - Default name for the module
   * @param {string} sourceDescription - Description of where the module was found
   * @returns {Object|null} Module info or null if not a valid module
   */
  async getModuleInfo(modulePath, defaultName, sourceDescription) {
    const moduleConfigPath = path.join(modulePath, 'module.yaml');

    if (!(await fs.pathExists(moduleConfigPath))) {
      // Check resolution cache for strategy 5 modules (no module.yaml on disk)
      const { CustomModuleManager } = require('./custom-module-manager');
      const customMgr = new CustomModuleManager();
      const resolved = customMgr.getResolution(defaultName);
      if (resolved && resolved.synthesizedModuleYaml) {
        return {
          id: resolved.code,
          path: modulePath,
          name: resolved.name,
          description: resolved.description,
          version: resolved.version || '1.0.0',
          source: sourceDescription,
          dependencies: [],
          defaultSelected: false,
        };
      }
      return null;
    }

    const moduleInfo = {
      id: defaultName,
      path: modulePath,
      name: defaultName
        .split('-')
        .map((word) => word.charAt(0).toUpperCase() + word.slice(1))
        .join(' '),
      description: 'BMAD Module',
      version: '5.0.0',
      source: sourceDescription,
    };

    // Read module config for metadata
    try {
      const configContent = await fs.readFile(moduleConfigPath, 'utf8');
      const config = yaml.parse(configContent);

      // Use the code property as the id if available
      if (config.code) {
        moduleInfo.id = config.code;
      }

      moduleInfo.name = config.name || moduleInfo.name;
      moduleInfo.description = config.description || moduleInfo.description;
      moduleInfo.version = config.version || moduleInfo.version;
      moduleInfo.dependencies = config.dependencies || [];
      moduleInfo.defaultSelected = config.default_selected === undefined ? false : config.default_selected;
    } catch (error) {
      await prompts.log.warn(`Failed to read config for ${defaultName}: ${error.message}`);
    }

    return moduleInfo;
  }

  /**
   * Find the source path for a module by searching all possible locations
   * @param {string} moduleCode - Code of the module to find (from module.yaml)
   * @returns {string|null} Path to the module source or null if not found
   */
  async findModuleSource(moduleCode, options = {}) {
    // Inherit channelOptions from the install-scoped instance when the caller
    // didn't pass one explicitly. Keeps pre-install config collection and the
    // actual install step looking at the same git ref.
    if (options.channelOptions === undefined && this.channelOptions) {
      options = { ...options, channelOptions: this.channelOptions };
    }
    const projectRoot = getProjectRoot();

    // Check for core module (directly under src/core-skills)
    if (moduleCode === 'core') {
      const corePath = getSourcePath('core-skills');
      if (await fs.pathExists(corePath)) {
        return corePath;
      }
    }

    // Check for built-in bmm module (directly under src/bmm-skills)
    if (moduleCode === 'bmm') {
      const bmmPath = getSourcePath('bmm-skills');
      if (await fs.pathExists(bmmPath)) {
        return bmmPath;
      }
    }

    // Check external official modules (pass channelOptions so channel plan applies)
    const externalSource = await this.externalModuleManager.findExternalModuleSource(moduleCode, options);
    if (externalSource) {
      return externalSource;
    }

    // Check custom modules (from user-provided URLs, already cloned to cache)
    const { CustomModuleManager } = require('./custom-module-manager');
    const customMgr = new CustomModuleManager();
    const customSource = await customMgr.findModuleSourceByCode(moduleCode, options);
    if (customSource) {
      return customSource;
    }

    return null;
  }

  /**
   * Install a module
   * @param {string} moduleName - Code of the module to install (from module.yaml)
   * @param {string} bmadDir - Target bmad directory
   * @param {Function} fileTrackingCallback - Optional callback to track installed files
   * @param {Object} options - Additional installation options
   * @param {Array<string>} options.installedIDEs - Array of IDE codes that were installed
   * @param {Object} options.moduleConfig - Module configuration from config collector
   * @param {Object} options.logger - Logger instance for output
   */
  async install(moduleName, bmadDir, fileTrackingCallback = null, options = {}) {
    // Check if this module has a plugin resolution (custom marketplace install)
    const { CustomModuleManager } = require('./custom-module-manager');
    const customMgr = new CustomModuleManager();
    const resolved = customMgr.getResolution(moduleName);
    if (resolved) {
      return this.installFromResolution(resolved, bmadDir, fileTrackingCallback, options);
    }

    const sourcePath = await this.findModuleSource(moduleName, {
      silent: options.silent,
      channelOptions: options.channelOptions,
    });
    const targetPath = path.join(bmadDir, moduleName);

    if (!sourcePath) {
      throw new Error(
        `Source for module '${moduleName}' is not available. It will be retained but cannot be updated without its source files.`,
      );
    }

    if (await fs.pathExists(targetPath)) {
      await fs.remove(targetPath);
    }

    // Marketplace-plugin registry modules keep their installable skills outside
    // the directory that holds module.yaml (sourcePath points at the -setup
    // skill's assets/), so they cannot be installed by copying sourcePath. Copy
    // the resolved skill directories instead, matching how custom marketplace
    // installs lay out a module. Everything else (manifest, version info) flows
    // through the standard external-module path below.
    const moduleInfo = await this.externalModuleManager.getModuleByCode(moduleName);
    if (moduleInfo && moduleInfo.marketplacePlugin) {
      const pluginResolution = this.externalModuleManager.getPluginResolution(moduleName);
      // Fail loud: copying sourcePath here would install only the -setup skill's
      // assets/ (module.yaml + module-help.csv) and none of the skills — a
      // silent, broken partial install. Abort instead.
      if (!pluginResolution || !Array.isArray(pluginResolution.skillPaths) || pluginResolution.skillPaths.length === 0) {
        throw new Error(
          `Module '${moduleName}' is registered as a marketplace plugin but its skills could not be resolved ` +
            `from .claude-plugin/marketplace.json (missing or malformed on the selected channel). ` +
            `Aborting to avoid a partial install with no skills.`,
        );
      }
      await this._copyResolvedSkills(pluginResolution, targetPath, fileTrackingCallback, options.moduleConfig, {
        installShims: options.installShims,
      });
    } else {
      await this.copyModuleWithFiltering(sourcePath, targetPath, fileTrackingCallback, options.moduleConfig, {
        installShims: options.installShims,
      });
    }

    if (!options.skipModuleInstaller) {
      await this.createModuleDirectories(moduleName, bmadDir, options);
    }

    const { Manifest } = require('../core/manifest');
    const manifestObj = new Manifest();
    const versionInfo = await manifestObj.getModuleVersionInfo(moduleName, bmadDir, sourcePath);

    // Pick up channel resolution recorded by the external manager (the only
    // manager that does pre-clone resolution now that community is retired).
    const resolution = this.externalModuleManager.getResolution(moduleName);

    await manifestObj.addModule(bmadDir, moduleName, {
      version: resolution?.version || versionInfo.version,
      source: versionInfo.source,
      npmPackage: versionInfo.npmPackage,
      repoUrl: versionInfo.repoUrl,
      channel: resolution?.channel,
      sha: resolution?.sha,
    });

    return { success: true, module: moduleName, path: targetPath, versionInfo };
  }

  /**
   * Lay out a PluginResolver resolution on disk: copy each resolved skill
   * directory (flattened by leaf name) into targetPath and place module-help.csv
   * at the module root. Shared by both custom marketplace installs
   * (installFromResolution) and official marketplace-plugin registry installs
   * (install), so the two paths cannot drift.
   * @param {Object} resolved - ResolvedModule from PluginResolver
   * @param {string} targetPath - Destination module directory (e.g. bmadDir/<code>)
   * @param {Function} fileTrackingCallback - Optional callback to track installed files
   * @param {Object} moduleConfig - Module configuration passed to copy filtering
   */
  async _copyResolvedSkills(resolved, targetPath, fileTrackingCallback = null, moduleConfig = {}, installOptions = {}) {
    await fs.ensureDir(targetPath);

    // Copy each skill directory, flattened by leaf name. Leaf names must be
    // unique — two skills that flatten to the same directory would silently
    // overwrite each other, so fail loud instead.
    const seenLeaves = new Map();
    for (const skillPath of resolved.skillPaths) {
      const skillDirName = path.basename(skillPath);
      if (seenLeaves.has(skillDirName)) {
        throw new Error(
          `Cannot install module '${resolved.code}': skill directories '${seenLeaves.get(skillDirName)}' and ` +
            `'${skillPath}' share the leaf name '${skillDirName}' and would overwrite each other. ` +
            `Skill directory names must be unique.`,
        );
      }
      seenLeaves.set(skillDirName, skillPath);
      const skillTarget = path.join(targetPath, skillDirName);
      await this.copyModuleWithFiltering(skillPath, skillTarget, fileTrackingCallback, moduleConfig, installOptions);
    }

    // Place module-help.csv at the module root.
    const helpTarget = path.join(targetPath, 'module-help.csv');
    if (resolved.moduleHelpCsvPath) {
      // Strategies 1-4: copy the existing file.
      await fs.copy(resolved.moduleHelpCsvPath, helpTarget, { overwrite: true });
      if (fileTrackingCallback) fileTrackingCallback(helpTarget);
    } else if (resolved.synthesizedHelpCsv) {
      // Strategy 5: write synthesized content.
      await fs.writeFile(helpTarget, resolved.synthesizedHelpCsv, 'utf8');
      if (fileTrackingCallback) fileTrackingCallback(helpTarget);
    }
  }

  /**
   * Install a module from a PluginResolver resolution result.
   * Copies specific skill directories and places module-help.csv at the target root.
   * @param {Object} resolved - ResolvedModule from PluginResolver
   * @param {string} bmadDir - Target bmad directory
   * @param {Function} fileTrackingCallback - Optional callback to track installed files
   * @param {Object} options - Installation options
   */
  async installFromResolution(resolved, bmadDir, fileTrackingCallback = null, options = {}) {
    const targetPath = path.join(bmadDir, resolved.code);

    if (await fs.pathExists(targetPath)) {
      await fs.remove(targetPath);
    }

    await this._copyResolvedSkills(resolved, targetPath, fileTrackingCallback, options.moduleConfig, {
      installShims: options.installShims,
    });

    // Create directories declared in module.yaml (strategies 1-4 may have these)
    if (!options.skipModuleInstaller) {
      await this.createModuleDirectories(resolved.code, bmadDir, options);
    }

    // Update manifest. For custom-source installs we derive channel from the
    // cloneRef (present → pinned, absent → next; local paths have no channel).
    const { Manifest } = require('../core/manifest');
    const manifestObj = new Manifest();

    const hasGitClone = !!resolved.repoUrl;
    const manifestEntry = {
      version: resolved.cloneRef || (hasGitClone ? 'main' : resolved.version || null),
      source: 'custom',
      npmPackage: null,
      repoUrl: resolved.repoUrl || null,
    };
    if (hasGitClone) {
      manifestEntry.channel = resolved.cloneRef ? 'pinned' : 'next';
      if (resolved.cloneSha) manifestEntry.sha = resolved.cloneSha;
      if (resolved.rawInput) manifestEntry.rawSource = resolved.rawInput;
    }
    if (resolved.localPath) manifestEntry.localPath = resolved.localPath;
    await manifestObj.addModule(bmadDir, resolved.code, manifestEntry);

    return {
      success: true,
      module: resolved.code,
      path: targetPath,
      // Mirror the manifestEntry.version precedence above so downstream summary
      // lines show the same string we just wrote to disk (custom git-backed
      // installs show the cloned ref or 'main').
      versionInfo: {
        version: resolved.cloneRef || (hasGitClone ? 'main' : resolved.version || ''),
      },
    };
  }

  /**
   * Update an existing module
   * @param {string} moduleName - Name of the module to update
   * @param {string} bmadDir - Target bmad directory
   */
  async update(moduleName, bmadDir) {
    const sourcePath = await this.findModuleSource(moduleName);
    const targetPath = path.join(bmadDir, moduleName);

    if (!sourcePath) {
      throw new Error(`Module '${moduleName}' not found in any source location`);
    }

    if (!(await fs.pathExists(targetPath))) {
      throw new Error(`Module '${moduleName}' is not installed`);
    }

    await this.syncModule(sourcePath, targetPath);

    return {
      success: true,
      module: moduleName,
      path: targetPath,
    };
  }

  /**
   * Remove a module
   * @param {string} moduleName - Name of the module to remove
   * @param {string} bmadDir - Target bmad directory
   */
  async remove(moduleName, bmadDir) {
    const targetPath = path.join(bmadDir, moduleName);

    if (!(await fs.pathExists(targetPath))) {
      throw new Error(`Module '${moduleName}' is not installed`);
    }

    await fs.remove(targetPath);

    return {
      success: true,
      module: moduleName,
    };
  }

  /**
   * Check if a module is installed
   * @param {string} moduleName - Name of the module
   * @param {string} bmadDir - Target bmad directory
   * @returns {boolean} True if module is installed
   */
  async isInstalled(moduleName, bmadDir) {
    const targetPath = path.join(bmadDir, moduleName);
    return await fs.pathExists(targetPath);
  }

  /**
   * Get installed module info
   * @param {string} moduleName - Name of the module
   * @param {string} bmadDir - Target bmad directory
   * @returns {Object|null} Module info or null if not installed
   */
  async getInstalledInfo(moduleName, bmadDir) {
    const targetPath = path.join(bmadDir, moduleName);

    if (!(await fs.pathExists(targetPath))) {
      return null;
    }

    const configPath = path.join(targetPath, 'config.yaml');
    const moduleInfo = {
      id: moduleName,
      path: targetPath,
      installed: true,
    };

    if (await fs.pathExists(configPath)) {
      try {
        const configContent = await fs.readFile(configPath, 'utf8');
        const config = yaml.parse(configContent);
        Object.assign(moduleInfo, config);
      } catch (error) {
        await prompts.log.warn(`Failed to read installed module config: ${error.message}`);
      }
    }

    return moduleInfo;
  }

  /**
   * Copy module with filtering for localskip agents and conditional content
   * @param {string} sourcePath - Source module path
   * @param {string} targetPath - Target module path
   * @param {Function} fileTrackingCallback - Optional callback to track installed files
   * @param {Object} moduleConfig - Module configuration with conditional flags
   */
  async copyModuleWithFiltering(sourcePath, targetPath, fileTrackingCallback = null, moduleConfig = {}, installOptions = {}) {
    // Get all files in source
    const sourceFiles = await this.getFileList(sourcePath);
    const shimDirectories =
      installOptions.installShims === false
        ? (await discoverShims(sourcePath)).map((shim) => shim.relativeDirectory.split(path.sep).join('/'))
        : [];

    for (const file of sourceFiles) {
      const normalizedFile = file.split(path.sep).join('/');
      if (shimDirectories.some((shimDir) => shimDir === '' || normalizedFile === shimDir || normalizedFile.startsWith(`${shimDir}/`))) {
        continue;
      }
      // Skip sub-modules directory - these are IDE-specific and handled separately
      if (file.startsWith('sub-modules/')) {
        continue;
      }

      // Skip sidecar directories - these contain agent-specific assets not needed at install time
      const isInSidecarDirectory = path
        .dirname(file)
        .split('/')
        .some((dir) => dir.toLowerCase().endsWith('-sidecar'));

      if (isInSidecarDirectory) {
        continue;
      }

      // Skip module.yaml at root - it's only needed at install time
      if (file === 'module.yaml') {
        continue;
      }

      // Skip module root config.yaml only - generated by config collector with actual values
      // Workflow-level config.yaml (e.g. workflows/orchestrate-story/config.yaml) must be copied
      // for custom modules that use workflow-specific configuration
      if (file === 'config.yaml') {
        continue;
      }

      const sourceFile = path.join(sourcePath, file);
      const targetFile = path.join(targetPath, file);

      // Check if this is an agent file
      if (file.startsWith('agents/') && file.endsWith('.md')) {
        // Read the file to check for localskip
        const content = await fs.readFile(sourceFile, 'utf8');

        // Check for localskip="true" in the agent tag
        const agentMatch = content.match(/<agent[^>]*\slocalskip="true"[^>]*>/);
        if (agentMatch) {
          await prompts.log.message(`  Skipping web-only agent: ${path.basename(file)}`);
          continue; // Skip this agent
        }
      }

      // Copy the file with placeholder replacement
      await this.copyFile(sourceFile, targetFile);

      // Track the file if callback provided
      if (fileTrackingCallback) {
        fileTrackingCallback(targetFile);
      }
    }
  }

  /**
   * Create directories declared in module.yaml's `directories` key
   * This replaces the security-risky module installer pattern with declarative config
   * During updates, if a directory path changed, moves the old directory to the new path
   * @param {string} moduleName - Name of the module
   * @param {string} bmadDir - Target bmad directory
   * @param {Object} options - Installation options
   * @param {Object} options.moduleConfig - Module configuration from config collector
   * @param {Object} options.existingModuleConfig - Previous module config (for detecting path changes during updates)
   * @param {Object} options.coreConfig - Core configuration
   * @returns {Promise<{createdDirs: string[], movedDirs: string[], createdWdsFolders: string[]}>} Created directories info
   */
  async createModuleDirectories(moduleName, bmadDir, options = {}) {
    const moduleConfig = options.moduleConfig || {};
    const existingModuleConfig = options.existingModuleConfig || {};
    const projectRoot = path.dirname(bmadDir);
    const emptyResult = { createdDirs: [], movedDirs: [], createdWdsFolders: [] };

    // Special handling for core module - it's in src/core-skills not src/modules
    let sourcePath;
    if (moduleName === 'core') {
      sourcePath = getSourcePath('core-skills');
    } else {
      sourcePath = await this.findModuleSource(moduleName, { silent: true });
      if (!sourcePath) {
        return emptyResult; // No source found, skip
      }
    }

    // Read module.yaml to find the `directories` key
    const moduleYamlPath = path.join(sourcePath, 'module.yaml');
    if (!(await fs.pathExists(moduleYamlPath))) {
      return emptyResult; // No module.yaml, skip
    }

    let moduleYaml;
    try {
      const yamlContent = await fs.readFile(moduleYamlPath, 'utf8');
      moduleYaml = yaml.parse(yamlContent);
    } catch (error) {
      await prompts.log.warn(`Invalid module.yaml for ${moduleName}: ${error.message}`);
      return emptyResult;
    }

    if (!moduleYaml || !moduleYaml.directories) {
      return emptyResult; // No directories declared, skip
    }

    const directories = moduleYaml.directories;
    const wdsFolders = moduleYaml.wds_folders || [];
    const createdDirs = [];
    const movedDirs = [];
    const createdWdsFolders = [];

    for (const dirRef of directories) {
      // Parse variable reference like "{design_artifacts}"
      const varMatch = dirRef.match(/^\{([^}]+)\}$/);
      if (!varMatch) {
        // Not a variable reference, skip
        continue;
      }

      const configKey = varMatch[1];
      const dirValue = moduleConfig[configKey];
      if (!dirValue || typeof dirValue !== 'string') {
        continue; // No value or not a string, skip
      }

      // Strip {project-root}/ prefix if present
      let dirPath = dirValue.replace(/^\{project-root\}\/?/, '');

      // Handle remaining {project-root} anywhere in the path
      dirPath = dirPath.replaceAll('{project-root}', '');

      // Resolve to absolute path
      const fullPath = path.join(projectRoot, dirPath);

      // Validate path is within project root (prevent directory traversal)
      const normalizedPath = path.normalize(fullPath);
      const normalizedRoot = path.normalize(projectRoot);
      if (!normalizedPath.startsWith(normalizedRoot + path.sep) && normalizedPath !== normalizedRoot) {
        const color = await prompts.getColor();
        await prompts.log.warn(color.yellow(`${configKey} path escapes project root, skipping: ${dirPath}`));
        continue;
      }

      // Check if directory path changed from previous config (update/modify scenario)
      const oldDirValue = existingModuleConfig[configKey];
      let oldFullPath = null;
      let oldDirPath = null;
      if (oldDirValue && typeof oldDirValue === 'string') {
        // F3: Normalize both values before comparing to avoid false negatives
        // from trailing slashes, separator differences, or prefix format variations
        let normalizedOld = oldDirValue.replace(/^\{project-root\}\/?/, '');
        normalizedOld = path.normalize(normalizedOld.replaceAll('{project-root}', ''));
        const normalizedNew = path.normalize(dirPath);

        if (normalizedOld !== normalizedNew) {
          oldDirPath = normalizedOld;
          oldFullPath = path.join(projectRoot, oldDirPath);
          const normalizedOldAbsolute = path.normalize(oldFullPath);
          if (!normalizedOldAbsolute.startsWith(normalizedRoot + path.sep) && normalizedOldAbsolute !== normalizedRoot) {
            oldFullPath = null; // Old path escapes project root, ignore it
          }

          // F13: Prevent parent/child move (e.g. docs/planning → docs/planning/v2)
          if (oldFullPath) {
            const normalizedNewAbsolute = path.normalize(fullPath);
            if (
              normalizedOldAbsolute.startsWith(normalizedNewAbsolute + path.sep) ||
              normalizedNewAbsolute.startsWith(normalizedOldAbsolute + path.sep)
            ) {
              const color = await prompts.getColor();
              await prompts.log.warn(
                color.yellow(
                  `${configKey}: cannot move between parent/child paths (${oldDirPath} / ${dirPath}), creating new directory instead`,
                ),
              );
              oldFullPath = null;
            }
          }
        }
      }

      const dirName = configKey.replaceAll('_', ' ');

      if (oldFullPath && (await fs.pathExists(oldFullPath)) && !(await fs.pathExists(fullPath))) {
        // Path changed and old dir exists → move old to new location
        // F1: Use fs.move() instead of fs.rename() for cross-device/volume support
        // F2: Wrap in try/catch — fallback to creating new dir on failure
        try {
          await fs.ensureDir(path.dirname(fullPath));
          await fs.move(oldFullPath, fullPath);
          movedDirs.push(`${dirName}: ${oldDirPath} → ${dirPath}`);
        } catch (moveError) {
          const color = await prompts.getColor();
          await prompts.log.warn(
            color.yellow(
              `Failed to move ${oldDirPath} → ${dirPath}: ${moveError.message}\n  Creating new directory instead. Please move contents from the old directory manually.`,
            ),
          );
          await fs.ensureDir(fullPath);
          createdDirs.push(`${dirName}: ${dirPath}`);
        }
      } else if (oldFullPath && (await fs.pathExists(oldFullPath)) && (await fs.pathExists(fullPath))) {
        // F5: Both old and new directories exist — warn user about potential orphaned documents
        const color = await prompts.getColor();
        await prompts.log.warn(
          color.yellow(
            `${dirName}: path changed but both directories exist:\n  Old: ${oldDirPath}\n  New: ${dirPath}\n  Old directory may contain orphaned documents — please review and merge manually.`,
          ),
        );
      } else if (!(await fs.pathExists(fullPath))) {
        // New directory doesn't exist yet → create it
        createdDirs.push(`${dirName}: ${dirPath}`);
        await fs.ensureDir(fullPath);
      }

      // Create WDS subfolders if this is the design_artifacts directory
      if (configKey === 'design_artifacts' && wdsFolders.length > 0) {
        for (const subfolder of wdsFolders) {
          const subPath = path.join(fullPath, subfolder);
          if (!(await fs.pathExists(subPath))) {
            await fs.ensureDir(subPath);
            createdWdsFolders.push(subfolder);
          }
        }
      }
    }

    return { createdDirs, movedDirs, createdWdsFolders };
  }

  /**
   * Private: Sync module files (preserving user modifications)
   * @param {string} sourcePath - Source module path
   * @param {string} targetPath - Target module path
   */
  async syncModule(sourcePath, targetPath) {
    // Get list of all source files
    const sourceFiles = await this.getFileList(sourcePath);

    for (const file of sourceFiles) {
      const sourceFile = path.join(sourcePath, file);
      const targetFile = path.join(targetPath, file);

      // Check if target file exists and has been modified
      if (await fs.pathExists(targetFile)) {
        const sourceStats = await fs.stat(sourceFile);
        const targetStats = await fs.stat(targetFile);

        // Skip if target is newer (user modified)
        if (targetStats.mtime > sourceStats.mtime) {
          continue;
        }
      }

      // Copy file with placeholder replacement
      await this.copyFile(sourceFile, targetFile);
    }
  }

  /**
   * Private: Get list of all files in a directory
   * @param {string} dir - Directory path
   * @param {string} baseDir - Base directory for relative paths
   * @returns {Array} List of relative file paths
   */
  async getFileList(dir, baseDir = dir) {
    const files = [];
    const entries = await fs.readdir(dir, { withFileTypes: true });

    for (const entry of entries) {
      const fullPath = path.join(dir, entry.name);

      if (entry.isDirectory()) {
        const subFiles = await this.getFileList(fullPath, baseDir);
        files.push(...subFiles);
      } else {
        files.push(path.relative(baseDir, fullPath));
      }
    }

    return files;
  }

  // ─── Config collection methods (merged from ConfigCollector) ───

  /**
   * Find the bmad installation directory in a project
   * V6+ installations can use ANY folder name but ALWAYS have _config/manifest.yaml
   * @param {string} projectDir - Project directory
   * @returns {Promise<string>} Path to bmad directory
   */
  async findBmadDir(projectDir) {
    // Check if project directory exists
    if (!(await fs.pathExists(projectDir))) {
      // Project doesn't exist yet, return default
      return path.join(projectDir, 'bmad');
    }

    // V6+ strategy: Look for ANY directory with _config/manifest.yaml
    // This is the definitive marker of a V6+ installation
    try {
      const entries = await fs.readdir(projectDir, { withFileTypes: true });
      for (const entry of entries) {
        if (entry.isDirectory()) {
          const manifestPath = path.join(projectDir, entry.name, '_config', 'manifest.yaml');
          if (await fs.pathExists(manifestPath)) {
            // Found a V6+ installation
            return path.join(projectDir, entry.name);
          }
        }
      }
    } catch {
      // Ignore errors, fall through to default
    }

    // No V6+ installation found, return default
    // This will be used for new installations
    return path.join(projectDir, 'bmad');
  }

  /**
   * Detect the existing BMAD folder name in a project
   * @param {string} projectDir - Project directory
   * @returns {Promise<string|null>} Folder name (just the name, not full path) or null if not found
   */
  async detectExistingBmadFolder(projectDir) {
    // Check if project directory exists
    if (!(await fs.pathExists(projectDir))) {
      return null;
    }

    // Look for ANY directory with _config/manifest.yaml
    try {
      const entries = await fs.readdir(projectDir, { withFileTypes: true });
      for (const entry of entries) {
        if (entry.isDirectory()) {
          const manifestPath = path.join(projectDir, entry.name, '_config', 'manifest.yaml');
          if (await fs.pathExists(manifestPath)) {
            // Found a V6+ installation, return just the folder name
            return entry.name;
          }
        }
      }
    } catch {
      // Ignore errors
    }

    return null;
  }

  /**
   * Load existing config if it exists from module config files
   * @param {string} projectDir - Target project directory
   */
  async loadExistingConfig(projectDir) {
    this._existingConfig = {};

    // Check if project directory exists first
    if (!(await fs.pathExists(projectDir))) {
      return false;
    }

    // Find the actual bmad directory (handles custom folder names)
    const bmadDir = await this.findBmadDir(projectDir);

    // Check if bmad directory exists
    if (!(await fs.pathExists(bmadDir))) {
      return false;
    }

    // Primary source: installer-written config.toml + config.user.toml (v6+).
    // Both files together hold all install answers; config.user.toml carries
    // user-scoped keys like user_name that would otherwise be re-prompted on
    // every reinstall.
    let foundAny = false;
    for (const fileName of ['config.toml', 'config.user.toml']) {
      const tomlPath = path.join(bmadDir, fileName);
      if (!(await fs.pathExists(tomlPath))) continue;
      try {
        const content = await fs.readFile(tomlPath, 'utf8');
        const parsed = parseCentralToml(content);
        for (const [section, values] of Object.entries(parsed)) {
          if (values && typeof values === 'object' && !Array.isArray(values)) {
            if (!this._existingConfig[section]) this._existingConfig[section] = {};
            Object.assign(this._existingConfig[section], values);
            foundAny = true;
          }
        }
      } catch {
        // Ignore parse errors
      }
    }

    if (foundAny) {
      return true;
    }

    // Fallback: legacy per-module config.yaml files (pre-v6 installations).
    const entries = await fs.readdir(bmadDir, { withFileTypes: true });
    const nonModuleDirs = new Set(['_config', '_memory', 'memory', 'docs', 'scripts', 'custom', 'render']);
    for (const entry of entries) {
      if (entry.isDirectory()) {
        if (nonModuleDirs.has(entry.name)) {
          continue;
        }

        const moduleConfigPath = path.join(bmadDir, entry.name, 'config.yaml');

        if (await fs.pathExists(moduleConfigPath)) {
          try {
            const content = await fs.readFile(moduleConfigPath, 'utf8');
            const moduleConfig = yaml.parse(content);
            // Only keep plain object parses. A corrupt config.yaml that parses
            // to a scalar or array would crash later code that does `key in cfg`
            // / `Object.keys(cfg)`; treat it the same as a parse error.
            if (moduleConfig && typeof moduleConfig === 'object' && !Array.isArray(moduleConfig)) {
              this._existingConfig[entry.name] = moduleConfig;
              foundAny = true;
            }
          } catch {
            // Ignore parse errors for individual modules
          }
        }
      }
    }

    if (foundAny) {
      await this._hoistCoreKeysFromLegacyModuleConfigs();
    }

    return foundAny;
  }

  /**
   * Migrate prior answers when a key has moved from a non-core module to core
   * (e.g. project_name moving from bmm to core in #2279). Without this, the
   * partition logic in writeCentralConfig drops the value from the bmm bucket
   * (because it's now a core key) without re-homing it under [core], so the
   * user's prior answer silently disappears on the next install/quick-update.
   */
  async _hoistCoreKeysFromLegacyModuleConfigs() {
    const coreSchemaPath = path.join(getSourcePath(), 'core-skills', 'module.yaml');
    if (!(await fs.pathExists(coreSchemaPath))) return;

    let coreSchema;
    try {
      coreSchema = yaml.parse(await fs.readFile(coreSchemaPath, 'utf8'));
    } catch {
      return;
    }
    if (!coreSchema || typeof coreSchema !== 'object') return;

    const coreKeys = new Set(
      Object.entries(coreSchema)
        .filter(([, v]) => v && typeof v === 'object' && 'prompt' in v)
        .map(([k]) => k),
    );
    if (coreKeys.size === 0) return;

    // Belt-and-suspenders: loadExistingConfig already filters non-object parses,
    // but anyone calling _hoistCoreKeysFromLegacyModuleConfigs in isolation (or
    // future code paths populating _existingConfig directly) shouldn't be able
    // to crash this with a scalar / array.
    const existingCore = this._existingConfig.core;
    this._existingConfig.core = existingCore && typeof existingCore === 'object' && !Array.isArray(existingCore) ? existingCore : {};

    for (const [moduleName, cfg] of Object.entries(this._existingConfig)) {
      if (moduleName === 'core' || !cfg || typeof cfg !== 'object' || Array.isArray(cfg)) continue;
      for (const key of Object.keys(cfg)) {
        if (!coreKeys.has(key)) continue;
        if (!(key in this._existingConfig.core)) {
          this._existingConfig.core[key] = cfg[key];
        }
        delete cfg[key];
      }
    }
  }

  /**
   * Pre-scan module schemas to gather metadata for the configuration gateway prompt.
   * Returns info about which modules have configurable options.
   * @param {Array} modules - List of non-core module names
   * @returns {Promise<Array>} Array of {moduleName, displayName, questionCount, hasFieldsWithoutDefaults}
   */
  async scanModuleSchemas(modules) {
    const metadataFields = new Set(['code', 'name', 'header', 'subheader', 'default_selected']);
    const results = [];

    for (const moduleName of modules) {
      // Resolve module.yaml path - standard location first, then OfficialModules search
      let moduleConfigPath = null;
      const standardPath = path.join(getModulePath(moduleName), 'module.yaml');
      if (await fs.pathExists(standardPath)) {
        moduleConfigPath = standardPath;
      } else {
        const moduleSourcePath = await this.findModuleSource(moduleName, { silent: true });
        if (moduleSourcePath) {
          moduleConfigPath = path.join(moduleSourcePath, 'module.yaml');
        }
      }

      if (!moduleConfigPath || !(await fs.pathExists(moduleConfigPath))) {
        continue;
      }

      try {
        const content = await fs.readFile(moduleConfigPath, 'utf8');
        const moduleConfig = yaml.parse(content);
        if (!moduleConfig) continue;

        const displayName = moduleConfig.header || `${moduleName.toUpperCase()} Module`;
        const configKeys = Object.keys(moduleConfig).filter((key) => key !== 'prompt');
        const questionKeys = configKeys.filter((key) => {
          if (metadataFields.has(key)) return false;
          const item = moduleConfig[key];
          return item && typeof item === 'object' && item.prompt;
        });

        const hasFieldsWithoutDefaults = questionKeys.some((key) => {
          const item = moduleConfig[key];
          return item.default === undefined || item.default === null || item.default === '';
        });

        results.push({
          moduleName,
          displayName,
          questionCount: questionKeys.length,
          hasFieldsWithoutDefaults,
        });
      } catch (error) {
        await prompts.log.warn(`Could not read schema for module "${moduleName}": ${error.message}`);
      }
    }

    return results;
  }

  /**
   * Collect configuration for all modules
   * @param {Array} modules - List of modules to configure (including 'core')
   * @param {string} projectDir - Target project directory
   * @param {Object} options - Additional options
   * @param {boolean} options.skipPrompts - Skip prompts and use defaults (for --yes flag)
   */
  async collectAllConfigurations(modules, projectDir, options = {}) {
    this.skipPrompts = options.skipPrompts || false;
    this.modulesToCustomize = undefined;
    await this.loadExistingConfig(projectDir);

    // Check if core was already collected (e.g., in early collection phase)
    const coreAlreadyCollected = this.collectedConfig.core && Object.keys(this.collectedConfig.core).length > 0;

    // If core wasn't already collected, include it
    const allModules = coreAlreadyCollected ? modules.filter((m) => m !== 'core') : ['core', ...modules.filter((m) => m !== 'core')];

    // Store all answers across modules for cross-referencing
    if (!this.allAnswers) {
      this.allAnswers = {};
    }

    // Split processing: core first, then gateway, then remaining modules
    const coreModules = allModules.filter((m) => m === 'core');
    const nonCoreModules = allModules.filter((m) => m !== 'core');

    // Collect core config first (always fully prompted)
    for (const moduleName of coreModules) {
      await this.collectModuleConfig(moduleName, projectDir);
    }

    // Show batch configuration gateway for non-core modules
    // Scan all non-core module schemas for display names and config metadata
    let scannedModules = [];
    if (!this.skipPrompts && nonCoreModules.length > 0) {
      scannedModules = await this.scanModuleSchemas(nonCoreModules);
      const customizableModules = scannedModules.filter((m) => m.questionCount > 0);

      if (customizableModules.length > 0) {
        const configMode = await prompts.select({
          message: 'Module configuration',
          choices: [
            { name: 'Express Setup', value: 'express', hint: 'accept all defaults (recommended)' },
            { name: 'Customize', value: 'customize', hint: 'choose modules to configure' },
          ],
          default: 'express',
        });

        if (configMode === 'customize') {
          const choices = customizableModules.map((m) => ({
            name: `${m.displayName} (${m.questionCount} option${m.questionCount === 1 ? '' : 's'})`,
            value: m.moduleName,
            hint: m.hasFieldsWithoutDefaults ? 'has fields without defaults' : undefined,
            checked: m.hasFieldsWithoutDefaults,
          }));
          const selected = await prompts.multiselect({
            message: 'Select modules to customize:',
            choices,
            required: false,
          });
          this.modulesToCustomize = new Set(selected);
        } else {
          // Express mode: no modules to customize
          this.modulesToCustomize = new Set();
        }
      } else {
        // All non-core modules have zero config - no gateway needed
        this.modulesToCustomize = new Set();
      }
    }

    // Collect remaining non-core modules
    if (this.modulesToCustomize === undefined) {
      // No gateway was shown (skipPrompts, no non-core modules, or direct call) - process all normally
      for (const moduleName of nonCoreModules) {
        await this.collectModuleConfig(moduleName, projectDir);
      }
    } else {
      // Split into default modules (tasks progress) and customized modules (interactive)
      const defaultModules = nonCoreModules.filter((m) => !this.modulesToCustomize.has(m));
      const customizeModules = nonCoreModules.filter((m) => this.modulesToCustomize.has(m));

      // Run default modules with a single spinner
      if (defaultModules.length > 0) {
        // Build display name map from all scanned modules for pre-call spinner messages
        const displayNameMap = new Map();
        for (const m of scannedModules) {
          displayNameMap.set(m.moduleName, m.displayName);
        }

        const configSpinner = await prompts.spinner();
        configSpinner.start('Configuring modules...');
        try {
          for (const moduleName of defaultModules) {
            const displayName = displayNameMap.get(moduleName) || moduleName.toUpperCase();
            configSpinner.message(`Configuring ${displayName}...`);
            try {
              this._silentConfig = true;
              await this.collectModuleConfig(moduleName, projectDir);
            } finally {
              this._silentConfig = false;
            }
          }
        } finally {
          configSpinner.stop(customizeModules.length > 0 ? 'Module defaults applied' : 'Module configuration complete');
        }
      }

      // Run customized modules individually (may show interactive prompts)
      for (const moduleName of customizeModules) {
        await this.collectModuleConfig(moduleName, projectDir);
      }

      if (customizeModules.length > 0) {
        await prompts.log.step('Module configuration complete');
      }
    }

    // Add metadata
    this.collectedConfig._meta = {
      version: require(path.join(getProjectRoot(), 'package.json')).version,
      installDate: new Date().toISOString(),
      lastModified: new Date().toISOString(),
    };

    return this.collectedConfig;
  }

  /**
   * Collect configuration for a single module (Quick Update mode - only new fields)
   * @param {string} moduleName - Module name
   * @param {string} projectDir - Target project directory
   * @param {boolean} silentMode - If true, only prompt for new/missing fields
   * @returns {boolean} True if new fields were prompted, false if all fields existed
   */
  async collectModuleConfigQuick(moduleName, projectDir, silentMode = true) {
    this.currentProjectDir = projectDir;
    // Load existing config if not already loaded
    if (!this._existingConfig) {
      await this.loadExistingConfig(projectDir);
    }

    // Initialize allAnswers if not already initialized
    if (!this.allAnswers) {
      this.allAnswers = {};
    }

    // Load module's config schema from module.yaml
    // First, try the standard src/modules location
    let moduleConfigPath = path.join(getModulePath(moduleName), 'module.yaml');

    // If not found in src/modules, we need to find it by searching the project
    if (!(await fs.pathExists(moduleConfigPath))) {
      const moduleSourcePath = await this.findModuleSource(moduleName, { silent: true });

      if (moduleSourcePath) {
        moduleConfigPath = path.join(moduleSourcePath, 'module.yaml');
      }
    }

    if (!(await fs.pathExists(moduleConfigPath))) {
      // No config schema for this module - use existing values
      if (this._existingConfig && this._existingConfig[moduleName]) {
        if (!this.collectedConfig[moduleName]) {
          this.collectedConfig[moduleName] = {};
        }
        this.collectedConfig[moduleName] = { ...this._existingConfig[moduleName] };
      }
      return false;
    }

    const configContent = await fs.readFile(moduleConfigPath, 'utf8');
    const moduleConfig = yaml.parse(configContent);

    if (!moduleConfig) {
      return false;
    }

    // Compare schema with existing config to find new/missing fields
    const configKeys = Object.keys(moduleConfig).filter((key) => key !== 'prompt');
    const existingKeys = this._existingConfig && this._existingConfig[moduleName] ? Object.keys(this._existingConfig[moduleName]) : [];

    // Check if this module has no configuration keys at all (like CIS)
    // Filter out metadata fields and only count actual config objects
    const metadataFields = new Set(['code', 'name', 'header', 'subheader', 'default_selected']);
    const actualConfigKeys = configKeys.filter((key) => !metadataFields.has(key));
    const hasNoConfig = actualConfigKeys.length === 0;

    // If module has no config keys at all, handle it specially
    if (hasNoConfig && moduleConfig.subheader) {
      const moduleDisplayName = moduleConfig.header || `${moduleName.toUpperCase()} Module`;
      await prompts.log.step(moduleDisplayName);
      await prompts.log.message(`  \u2713 ${moduleConfig.subheader}`);
      return false; // No new fields
    }

    // Find new interactive fields (with prompt)
    const newKeys = configKeys.filter((key) => {
      const item = moduleConfig[key];
      // Check if it's a config item and doesn't exist in existing config
      return item && typeof item === 'object' && item.prompt && !existingKeys.includes(key);
    });

    // Find new static fields (without prompt, just result)
    const newStaticKeys = configKeys.filter((key) => {
      const item = moduleConfig[key];
      return item && typeof item === 'object' && !item.prompt && item.result && !existingKeys.includes(key);
    });

    // If in silent mode and no new keys (neither interactive nor static), use existing config and skip prompts
    if (silentMode && newKeys.length === 0 && newStaticKeys.length === 0) {
      if (this._existingConfig && this._existingConfig[moduleName]) {
        if (!this.collectedConfig[moduleName]) {
          this.collectedConfig[moduleName] = {};
        }
        this.collectedConfig[moduleName] = { ...this._existingConfig[moduleName] };

        // Special handling for user_name: ensure it has a value
        if (
          moduleName === 'core' &&
          (!this.collectedConfig[moduleName].user_name || this.collectedConfig[moduleName].user_name === '[USER_NAME]')
        ) {
          this.collectedConfig[moduleName].user_name = this.getDefaultUsername();
        }

        // Also populate allAnswers for cross-referencing
        for (const [key, value] of Object.entries(this._existingConfig[moduleName])) {
          // Ensure user_name is properly set in allAnswers too
          let finalValue = value;
          if (moduleName === 'core' && key === 'user_name' && (!value || value === '[USER_NAME]')) {
            finalValue = this.getDefaultUsername();
          }
          this.allAnswers[`${moduleName}_${key}`] = finalValue;
        }
      } else if (moduleName === 'core') {
        // No existing core config - ensure we at least have user_name
        if (!this.collectedConfig[moduleName]) {
          this.collectedConfig[moduleName] = {};
        }
        if (!this.collectedConfig[moduleName].user_name) {
          this.collectedConfig[moduleName].user_name = this.getDefaultUsername();
          this.allAnswers[`${moduleName}_user_name`] = this.getDefaultUsername();
        }
      }

      // Show "no config" message for modules with no new questions (that have config keys)
      await prompts.log.message(`  \u2713 ${moduleName.toUpperCase()} module already up to date`);
      return false; // No new fields
    }

    // If we have new fields (interactive or static), process them
    if (newKeys.length > 0 || newStaticKeys.length > 0) {
      const questions = [];
      const staticAnswers = {};

      // Build questions for interactive fields
      for (const key of newKeys) {
        const item = moduleConfig[key];
        const question = await this.buildQuestion(moduleName, key, item, moduleConfig);
        if (question) {
          questions.push(question);
        }
      }

      // Prepare static answers (no prompt, just result)
      for (const key of newStaticKeys) {
        staticAnswers[`${moduleName}_${key}`] = undefined;
      }

      // Collect all answers (static + prompted)
      let allAnswers = { ...staticAnswers };

      if (questions.length > 0 && silentMode) {
        // In silent mode (quick update), use defaults for new fields instead of prompting
        for (const q of questions) {
          allAnswers[q.name] = typeof q.default === 'function' ? q.default({}) : q.default;
        }
        await prompts.log.message(`  \u2713 ${moduleName.toUpperCase()} module configured with defaults`);
      } else if (questions.length > 0) {
        // Only show header if we actually have questions
        await CLIUtils.displayModuleConfigHeader(moduleName, moduleConfig.header, moduleConfig.subheader);
        await prompts.log.message('');
        const promptedAnswers = await prompts.prompt(questions);

        // Merge prompted answers with static answers
        Object.assign(allAnswers, promptedAnswers);
      } else if (newStaticKeys.length > 0) {
        // Only static fields, no questions - show no config message
        await prompts.log.message(`  \u2713 ${moduleName.toUpperCase()} module configuration updated`);
      }

      // Store all answers for cross-referencing
      Object.assign(this.allAnswers, allAnswers);

      // Process all answers (both static and prompted)
      // First, copy existing config to preserve values that aren't being updated
      if (this._existingConfig && this._existingConfig[moduleName]) {
        this.collectedConfig[moduleName] = { ...this._existingConfig[moduleName] };
      } else {
        this.collectedConfig[moduleName] = {};
      }

      for (const key of Object.keys(allAnswers)) {
        const originalKey = key.replace(`${moduleName}_`, '');
        const item = moduleConfig[originalKey];
        const value = allAnswers[key];

        let result;
        if (Array.isArray(value)) {
          result = value;
        } else if (item.result) {
          result = this.processResultTemplate(item.result, value);
        } else {
          result = value;
        }

        // Update the collected config with new/updated values
        this.collectedConfig[moduleName][originalKey] = result;
      }
    }

    // Copy over existing values for fields that weren't prompted
    if (this._existingConfig && this._existingConfig[moduleName]) {
      if (!this.collectedConfig[moduleName]) {
        this.collectedConfig[moduleName] = {};
      }
      for (const [key, value] of Object.entries(this._existingConfig[moduleName])) {
        if (!this.collectedConfig[moduleName][key]) {
          this.collectedConfig[moduleName][key] = value;
          this.allAnswers[`${moduleName}_${key}`] = value;
        }
      }
    }

    await this.displayModulePostConfigNotes(moduleName, moduleConfig);

    return newKeys.length > 0 || newStaticKeys.length > 0; // Return true if we had any new fields (interactive or static)
  }

  /**
   * Process a result template with value substitution
   * @param {*} resultTemplate - The result template
   * @param {*} value - The value to substitute
   * @returns {*} Processed result
   */
  processResultTemplate(resultTemplate, value) {
    let result = resultTemplate;

    if (typeof result === 'string' && value !== undefined) {
      if (typeof value === 'string') {
        result = result.replace('{value}', value);
      } else if (typeof value === 'boolean' || typeof value === 'number') {
        if (result === '{value}') {
          result = value;
        } else {
          result = result.replace('{value}', value);
        }
      } else {
        result = value;
      }

      if (typeof result === 'string') {
        result = result.replaceAll(/{([^}]+)}/g, (match, configKey) => {
          if (configKey === 'project-root') {
            return '{project-root}';
          }
          if (configKey === 'value') {
            return match;
          }

          let configValue = this.allAnswers[configKey] || this.allAnswers[`${configKey}`];
          if (!configValue) {
            for (const [answerKey, answerValue] of Object.entries(this.allAnswers)) {
              if (answerKey.endsWith(`_${configKey}`)) {
                configValue = answerValue;
                break;
              }
            }
          }

          if (!configValue) {
            for (const mod of Object.keys(this.collectedConfig)) {
              if (mod !== '_meta' && this.collectedConfig[mod] && this.collectedConfig[mod][configKey]) {
                configValue = this.collectedConfig[mod][configKey];
                if (typeof configValue === 'string' && configValue.includes('{project-root}/')) {
                  configValue = configValue.replace('{project-root}/', '');
                }
                break;
              }
            }
          }

          return configValue || match;
        });
      }
    }

    return result;
  }

  /**
   * Get the default username from the system
   * @returns {string} Capitalized username\
   */
  getDefaultUsername() {
    let result = 'BMad';
    try {
      const os = require('node:os');
      const userInfo = os.userInfo();
      if (userInfo && userInfo.username) {
        const username = userInfo.username;
        result = username.charAt(0).toUpperCase() + username.slice(1);
      }
    } catch {
      // Do nothing, just return 'BMad'
    }
    return result;
  }

  /**
   * Collect configuration for a single module
   * @param {string} moduleName - Module name
   * @param {string} projectDir - Target project directory
   * @param {boolean} skipLoadExisting - Skip loading existing config (for early core collection)
   * @param {boolean} skipCompletion - Skip showing completion message (for early core collection)
   */
  async collectModuleConfig(moduleName, projectDir, skipLoadExisting = false, skipCompletion = false) {
    this.currentProjectDir = projectDir;
    // Load existing config if needed and not already loaded
    if (!skipLoadExisting && !this._existingConfig) {
      await this.loadExistingConfig(projectDir);
    }

    // Initialize allAnswers if not already initialized
    if (!this.allAnswers) {
      this.allAnswers = {};
    }
    // Load module's config
    let moduleConfigPath = path.join(getModulePath(moduleName), 'module.yaml');

    // If not found in src/modules or custom paths, search the project
    if (!(await fs.pathExists(moduleConfigPath))) {
      const moduleSourcePath = await this.findModuleSource(moduleName, { silent: true });

      if (moduleSourcePath) {
        moduleConfigPath = path.join(moduleSourcePath, 'module.yaml');
      }
    }

    let configPath = null;
    if (await fs.pathExists(moduleConfigPath)) {
      configPath = moduleConfigPath;
    } else {
      // No config for this module
      return;
    }

    const configContent = await fs.readFile(configPath, 'utf8');
    const moduleConfig = yaml.parse(configContent);

    if (!moduleConfig) {
      return;
    }

    // Process each config item
    const questions = [];
    const staticAnswers = {};
    const configKeys = Object.keys(moduleConfig).filter((key) => key !== 'prompt');

    for (const key of configKeys) {
      const item = moduleConfig[key];

      // Skip if not a config object
      if (!item || typeof item !== 'object') {
        continue;
      }

      // Handle static values (no prompt, just result)
      if (!item.prompt && item.result) {
        // Add to static answers with a marker value
        staticAnswers[`${moduleName}_${key}`] = undefined;
        continue;
      }

      // Handle interactive values (with prompt)
      if (item.prompt) {
        const question = await this.buildQuestion(moduleName, key, item, moduleConfig);
        if (question) {
          questions.push(question);
        }
      }
    }

    // Collect all answers (static + prompted)
    let allAnswers = { ...staticAnswers };

    // If there are questions to ask, prompt for accepting defaults vs customizing
    if (questions.length > 0) {
      const moduleDisplayName = moduleConfig.header || `${moduleName.toUpperCase()} Module`;

      // Skip prompts mode: use all defaults without asking
      if (this.skipPrompts) {
        await prompts.log.info(`Using default configuration for ${moduleDisplayName}`);
        // Use defaults for all questions
        for (const question of questions) {
          const hasDefault = question.default !== undefined && question.default !== null && question.default !== '';
          if (hasDefault && typeof question.default !== 'function') {
            allAnswers[question.name] = question.default;
          }
        }
      } else {
        if (!this._silentConfig) await prompts.log.step(`Configuring ${moduleDisplayName}`);
        let useDefaults = true;
        if (moduleName === 'core') {
          useDefaults = false; // Core: always show all questions
        } else if (this.modulesToCustomize === undefined) {
          // Fallback: original per-module confirm (backward compat for direct calls)
          const customizeAnswer = await prompts.prompt([
            {
              type: 'confirm',
              name: 'customize',
              message: 'Accept Defaults (no to customize)?',
              default: true,
            },
          ]);
          useDefaults = customizeAnswer.customize;
        } else {
          // Batch mode: use defaults unless module was selected for customization
          useDefaults = !this.modulesToCustomize.has(moduleName);
        }

        if (useDefaults && moduleName !== 'core') {
          // Accept defaults - only ask questions that have NO default value
          const questionsWithoutDefaults = questions.filter((q) => q.default === undefined || q.default === null || q.default === '');

          if (questionsWithoutDefaults.length > 0) {
            await prompts.log.message(`  Asking required questions for ${moduleName.toUpperCase()}...`);
            const promptedAnswers = await prompts.prompt(questionsWithoutDefaults);
            Object.assign(allAnswers, promptedAnswers);
          }

          // For questions with defaults that weren't asked, we need to process them with their default values
          const questionsWithDefaults = questions.filter((q) => q.default !== undefined && q.default !== null && q.default !== '');
          for (const question of questionsWithDefaults) {
            // Skip function defaults - these are dynamic and will be evaluated later
            if (typeof question.default === 'function') {
              continue;
            }
            allAnswers[question.name] = question.default;
          }
        } else {
          const promptedAnswers = await prompts.prompt(questions);
          Object.assign(allAnswers, promptedAnswers);
        }
      }
    }

    // Store all answers for cross-referencing
    Object.assign(this.allAnswers, allAnswers);

    // Process all answers (both static and prompted)
    // Always process if we have any answers or static answers
    if (Object.keys(allAnswers).length > 0 || Object.keys(staticAnswers).length > 0) {
      const answers = allAnswers;

      // Process answers and build result values
      for (const key of Object.keys(answers)) {
        const originalKey = key.replace(`${moduleName}_`, '');
        const item = moduleConfig[originalKey];
        const value = answers[key];

        // Build the result using the template
        let result;

        // For arrays (multi-select), handle differently
        if (Array.isArray(value)) {
          result = value;
        } else if (item.result) {
          result = item.result;

          // Replace placeholders only for strings
          if (typeof result === 'string' && value !== undefined) {
            // Replace {value} with the actual value
            if (typeof value === 'string') {
              result = result.replace('{value}', value);
            } else if (typeof value === 'boolean' || typeof value === 'number') {
              // For boolean and number values, if result is just "{value}", use the raw value
              if (result === '{value}') {
                result = value;
              } else {
                result = result.replace('{value}', value);
              }
            } else {
              result = value;
            }

            // Only do further replacements if result is still a string
            if (typeof result === 'string') {
              // Replace references to other config values
              result = result.replaceAll(/{([^}]+)}/g, (match, configKey) => {
                // Check if it's a special placeholder
                if (configKey === 'project-root') {
                  return '{project-root}';
                }

                // Skip if it's the 'value' placeholder we already handled
                if (configKey === 'value') {
                  return match;
                }

                // Look for the config value across all modules
                // First check if it's in the current module's answers
                let configValue = answers[`${moduleName}_${configKey}`];

                // Then check all answers (for cross-module references like outputFolder)
                if (!configValue) {
                  // Try with various module prefixes
                  for (const [answerKey, answerValue] of Object.entries(this.allAnswers)) {
                    if (answerKey.endsWith(`_${configKey}`)) {
                      configValue = answerValue;
                      break;
                    }
                  }
                }

                // Check in already collected config
                if (!configValue) {
                  for (const mod of Object.keys(this.collectedConfig)) {
                    if (mod !== '_meta' && this.collectedConfig[mod] && this.collectedConfig[mod][configKey]) {
                      configValue = this.collectedConfig[mod][configKey];
                      break;
                    }
                  }
                }

                return configValue || match;
              });
            }
          }
        } else {
          result = value;
        }

        // Store only the result value (no prompts, defaults, examples, etc.)
        if (!this.collectedConfig[moduleName]) {
          this.collectedConfig[moduleName] = {};
        }
        this.collectedConfig[moduleName][originalKey] = result;
      }

      // No longer display completion boxes - keep output clean
    } else {
      // No questions for this module - show completion message with header if available
      const moduleDisplayName = moduleConfig.header || `${moduleName.toUpperCase()} Module`;

      // Check if this module has NO configuration keys at all (like CIS)
      // Filter out metadata fields and only count actual config objects
      const metadataFields = new Set(['code', 'name', 'header', 'subheader', 'default_selected']);
      const actualConfigKeys = configKeys.filter((key) => !metadataFields.has(key));
      const hasNoConfig = actualConfigKeys.length === 0;

      if (!this._silentConfig) {
        if (hasNoConfig && (moduleConfig.subheader || moduleConfig.header)) {
          await prompts.log.step(moduleDisplayName);
          if (moduleConfig.subheader) {
            await prompts.log.message(`  \u2713 ${moduleConfig.subheader}`);
          } else {
            await prompts.log.message(`  \u2713 No custom configuration required`);
          }
        } else {
          // Module has config but just no questions to ask
          await prompts.log.message(`  \u2713 ${moduleName.toUpperCase()} module configured`);
        }
      }
    }

    // If we have no collected config for this module, but we have a module schema,
    // ensure we have at least an empty object
    if (!this.collectedConfig[moduleName]) {
      this.collectedConfig[moduleName] = {};

      // If we accepted defaults and have no answers, we still need to check
      // if there are any static values in the schema that should be applied
      if (moduleConfig) {
        for (const key of Object.keys(moduleConfig)) {
          if (key !== 'prompt' && moduleConfig[key] && typeof moduleConfig[key] === 'object') {
            const item = moduleConfig[key];
            // For static items (no prompt, just result), apply the result
            if (!item.prompt && item.result) {
              // Apply any placeholder replacements to the result
              let result = item.result;
              if (typeof result === 'string') {
                result = this.replacePlaceholders(result, moduleName, moduleConfig);
              }
              this.collectedConfig[moduleName][key] = result;
            }
          }
        }
      }
    }

    await this.displayModulePostConfigNotes(moduleName, moduleConfig);
  }

  /**
   * Replace placeholders in a string with collected config values
   * @param {string} str - String with placeholders
   * @param {string} currentModule - Current module name (to look up defaults in same module)
   * @param {Object} moduleConfig - Current module's config schema (to look up defaults)
   * @returns {string} String with placeholders replaced
   */
  replacePlaceholders(str, currentModule = null, moduleConfig = null) {
    if (typeof str !== 'string') {
      return str;
    }

    return str.replaceAll(/{([^}]+)}/g, (match, configKey) => {
      // Preserve special placeholders
      if (configKey === 'project-root' || configKey === 'value' || configKey === 'directory_name') {
        return match;
      }

      const configValue = this.resolveConfigValue(configKey, currentModule, moduleConfig);

      return configValue || match;
    });
  }

  /**
   * Clean a stored path-like value for prompt display/input reuse.
   * @param {*} value - Stored value
   * @returns {*} Cleaned value
   */
  cleanPromptValue(value) {
    if (typeof value === 'string' && value.startsWith('{project-root}/')) {
      return value.replace('{project-root}/', '');
    }

    return value;
  }

  /**
   * Resolve a config key from answers, collected config, existing config, or schema defaults.
   * @param {string} configKey - Config key to resolve
   * @param {string} currentModule - Current module name
   * @param {Object} moduleConfig - Current module config schema
   * @returns {*} Resolved value
   */
  resolveConfigValue(configKey, currentModule = null, moduleConfig = null) {
    // Look for the config value in allAnswers (already answered questions)
    let configValue = this.allAnswers?.[configKey] || this.allAnswers?.[`core_${configKey}`];

    if (!configValue && this.allAnswers) {
      for (const [answerKey, answerValue] of Object.entries(this.allAnswers)) {
        if (answerKey.endsWith(`_${configKey}`)) {
          configValue = answerValue;
          break;
        }
      }
    }

    // Prefer the current module's persisted value when re-prompting an existing install
    if (!configValue && currentModule && this._existingConfig?.[currentModule]?.[configKey] !== undefined) {
      configValue = this._existingConfig[currentModule][configKey];
    }

    // Check in already collected config
    if (!configValue) {
      for (const mod of Object.keys(this.collectedConfig)) {
        if (mod !== '_meta' && this.collectedConfig[mod] && this.collectedConfig[mod][configKey]) {
          configValue = this.collectedConfig[mod][configKey];
          break;
        }
      }
    }

    // Fall back to other existing module config values
    if (!configValue && this._existingConfig) {
      for (const mod of Object.keys(this._existingConfig)) {
        if (mod !== '_meta' && this._existingConfig[mod] && this._existingConfig[mod][configKey]) {
          configValue = this._existingConfig[mod][configKey];
          break;
        }
      }
    }

    // If still not found and we're in the same module, use the default from the config schema
    if (!configValue && currentModule && moduleConfig && moduleConfig[configKey]) {
      const referencedItem = moduleConfig[configKey];
      if (referencedItem && referencedItem.default !== undefined) {
        configValue = referencedItem.default;
      }
    }

    return this.cleanPromptValue(configValue);
  }

  /**
   * Convert an existing stored value back into the prompt-facing value for templated fields.
   * For example, "{test_artifacts}/{value}" + "_bmad-output/test-artifacts/test-design"
   * becomes "test-design" so the template is not applied twice on modify.
   * @param {*} existingValue - Stored config value
   * @param {string} moduleName - Module name
   * @param {Object} item - Config item definition
   * @param {Object} moduleConfig - Current module config schema
   * @returns {*} Prompt-facing default value
   */
  normalizeExistingValueForPrompt(existingValue, moduleName, item, moduleConfig = null) {
    const cleanedValue = this.cleanPromptValue(existingValue);

    if (typeof cleanedValue !== 'string' || typeof item?.result !== 'string' || !item.result.includes('{value}')) {
      return cleanedValue;
    }

    const [prefixTemplate = '', suffixTemplate = ''] = item.result.split('{value}');
    const prefix = this.cleanPromptValue(this.replacePlaceholders(prefixTemplate, moduleName, moduleConfig));
    const suffix = this.cleanPromptValue(this.replacePlaceholders(suffixTemplate, moduleName, moduleConfig));

    if ((prefix && !cleanedValue.startsWith(prefix)) || (suffix && !cleanedValue.endsWith(suffix))) {
      return cleanedValue;
    }

    const startIndex = prefix.length;
    const endIndex = suffix ? cleanedValue.length - suffix.length : cleanedValue.length;
    if (endIndex < startIndex) {
      return cleanedValue;
    }

    let promptValue = cleanedValue.slice(startIndex, endIndex);
    if (promptValue.startsWith('/')) {
      promptValue = promptValue.slice(1);
    }
    if (promptValue.endsWith('/')) {
      promptValue = promptValue.slice(0, -1);
    }

    return promptValue || cleanedValue;
  }

  /**
   * Build a prompt question from a config item
   * @param {string} moduleName - Module name
   * @param {string} key - Config key
   * @param {Object} item - Config item definition
   * @param {Object} moduleConfig - Full module config schema (for resolving defaults)
   */
  async buildQuestion(moduleName, key, item, moduleConfig = null) {
    const questionName = `${moduleName}_${key}`;

    // Check for existing value
    let existingValue = null;
    if (this._existingConfig && this._existingConfig[moduleName]) {
      existingValue = this._existingConfig[moduleName][key];
      existingValue = this.normalizeExistingValueForPrompt(existingValue, moduleName, item, moduleConfig);
    }

    // Special handling for user_name: default to system user
    if (moduleName === 'core' && key === 'user_name' && !existingValue) {
      item.default = this.getDefaultUsername();
    }

    // Determine question type and default value
    let questionType = 'input';
    let defaultValue = item.default;
    let choices = null;

    // Check if default contains references to other fields in the same module
    const hasSameModuleReference = typeof defaultValue === 'string' && defaultValue.match(/{([^}]+)}/);
    let dynamicDefault = false;

    // Replace placeholders in default value with collected config values
    if (typeof defaultValue === 'string') {
      if (defaultValue.includes('{directory_name}') && this.currentProjectDir) {
        const dirName = path.basename(this.currentProjectDir);
        defaultValue = defaultValue.replaceAll('{directory_name}', dirName);
      }

      // Check if this references another field in the same module (for dynamic defaults)
      if (hasSameModuleReference && moduleConfig) {
        const matches = defaultValue.match(/{([^}]+)}/g);
        if (matches) {
          for (const match of matches) {
            const fieldName = match.slice(1, -1); // Remove { }
            // Check if this field exists in the same module config
            if (moduleConfig[fieldName]) {
              dynamicDefault = true;
              break;
            }
          }
        }
      }

      // If not dynamic, replace placeholders now
      if (!dynamicDefault) {
        defaultValue = this.replacePlaceholders(defaultValue, moduleName, moduleConfig);
      }

      // Strip {project-root}/ from defaults since it will be added back by result template
      // This makes the display cleaner and user input simpler
      if (defaultValue.includes('{project-root}/')) {
        defaultValue = defaultValue.replace('{project-root}/', '');
      }
    }

    // Handle different question types
    if (item['single-select']) {
      questionType = 'list';
      choices = item['single-select'].map((choice) => {
        // If choice is an object with label and value
        if (typeof choice === 'object' && choice.label && choice.value !== undefined) {
          return {
            name: choice.label,
            value: choice.value,
          };
        }
        // Otherwise it's a simple string choice
        return {
          name: choice,
          value: choice,
        };
      });
      if (existingValue) {
        defaultValue = existingValue;
      }
    } else if (item['multi-select']) {
      questionType = 'checkbox';
      choices = item['multi-select'].map((choice) => {
        // If choice is an object with label and value
        if (typeof choice === 'object' && choice.label && choice.value !== undefined) {
          return {
            name: choice.label,
            value: choice.value,
            checked: existingValue
              ? existingValue.includes(choice.value)
              : item.default && Array.isArray(item.default)
                ? item.default.includes(choice.value)
                : false,
          };
        }
        // Otherwise it's a simple string choice
        return {
          name: choice,
          value: choice,
          checked: existingValue
            ? existingValue.includes(choice)
            : item.default && Array.isArray(item.default)
              ? item.default.includes(choice)
              : false,
        };
      });
    } else if (typeof defaultValue === 'boolean') {
      questionType = 'confirm';
    }

    // Build the prompt message
    let message = '';

    // Handle array prompts for multi-line messages
    if (Array.isArray(item.prompt)) {
      message = item.prompt.join('\n');
    } else {
      message = item.prompt;
    }

    // Replace placeholders in prompt message with collected config values
    if (typeof message === 'string') {
      message = this.replacePlaceholders(message, moduleName, moduleConfig);
    }

    // Add current value indicator for existing configs
    const color = await prompts.getColor();
    if (existingValue !== null && existingValue !== undefined) {
      if (typeof existingValue === 'boolean') {
        message += color.dim(` (current: ${existingValue ? 'true' : 'false'})`);
      } else if (Array.isArray(existingValue)) {
        message += color.dim(` (current: ${existingValue.join(', ')})`);
      } else if (questionType !== 'list') {
        // Show the cleaned value (without {project-root}/) for display
        message += color.dim(` (current: ${existingValue})`);
      }
    } else if (item.example && questionType === 'input') {
      // Show example for input fields
      let exampleText = typeof item.example === 'string' ? item.example : JSON.stringify(item.example);
      // Replace placeholders in example
      if (typeof exampleText === 'string') {
        exampleText = this.replacePlaceholders(exampleText, moduleName, moduleConfig);
        exampleText = exampleText.replace('{project-root}/', '');
      }
      message += color.dim(` (e.g., ${exampleText})`);
    }

    // Build the question object
    const question = {
      type: questionType,
      name: questionName,
      message: message,
    };

    // Set default - if it's dynamic, use a function that the prompt will evaluate with current answers
    // But if we have an existing value, always use that instead
    if (existingValue !== null && existingValue !== undefined && questionType !== 'list') {
      question.default = existingValue;
    } else if (dynamicDefault && typeof item.default === 'string') {
      const originalDefault = item.default;
      question.default = (answers) => {
        // Replace placeholders using answers from previous questions in the same batch
        let resolved = originalDefault;
        resolved = resolved.replaceAll(/{([^}]+)}/g, (match, fieldName) => {
          // Look for the answer in the current batch (prefixed with module name)
          const answerKey = `${moduleName}_${fieldName}`;
          if (answers[answerKey] !== undefined) {
            return answers[answerKey];
          }
          // Fall back to collected config
          return this.collectedConfig[moduleName]?.[fieldName] || match;
        });
        // Strip {project-root}/ for cleaner display
        if (resolved.includes('{project-root}/')) {
          resolved = resolved.replace('{project-root}/', '');
        }
        return resolved;
      };
    } else {
      question.default = defaultValue;
    }

    // Add choices for select types
    if (choices) {
      question.choices = choices;
    }

    // Add validation for input fields
    if (questionType === 'input') {
      question.validate = (input) => {
        if (!input && item.required) {
          return 'This field is required';
        }
        // Validate against regex pattern if provided
        if (input && item.regex) {
          const regex = new RegExp(item.regex);
          if (!regex.test(input)) {
            return `Invalid format. Must match pattern: ${item.regex}`;
          }
        }
        return true;
      };
    }

    // Add validation for checkbox (multi-select) fields
    if (questionType === 'checkbox' && item.required) {
      question.validate = (answers) => {
        if (!answers || answers.length === 0) {
          return 'At least one option must be selected';
        }
        return true;
      };
    }

    return question;
  }

  /**
   * Display post-configuration notes for a module
   * Shows prerequisite guidance based on collected config values
   * Reads notes from the module's `post-install-notes` section in module.yaml
   * Supports two formats:
   *   - Simple string: always displayed
   *   - Object keyed by config field name, with value-specific messages
   * @param {string} moduleName - Module name
   * @param {Object} moduleConfig - Parsed module.yaml content
   */
  async displayModulePostConfigNotes(moduleName, moduleConfig) {
    if (this._silentConfig) return;
    if (!moduleConfig || !moduleConfig['post-install-notes']) return;

    const notes = moduleConfig['post-install-notes'];
    const color = await prompts.getColor();

    // Format 1: Simple string - always display
    if (typeof notes === 'string') {
      await prompts.log.message('');
      for (const line of notes.trim().split('\n')) {
        await prompts.log.message(color.dim(line));
      }
      return;
    }

    // Format 2: Conditional on config values
    if (typeof notes === 'object') {
      const config = this.collectedConfig[moduleName];
      if (!config) return;

      let hasOutput = false;
      for (const [configKey, valueMessages] of Object.entries(notes)) {
        const selectedValue = config[configKey];
        if (!selectedValue || !valueMessages[selectedValue]) continue;

        if (hasOutput) await prompts.log.message('');
        hasOutput = true;

        const message = valueMessages[selectedValue];
        for (const line of message.trim().split('\n')) {
          const trimmedLine = line.trim();
          if (trimmedLine.endsWith(':') && !trimmedLine.startsWith(' ')) {
            await prompts.log.info(color.bold(trimmedLine));
          } else {
            await prompts.log.message(color.dim('  ' + trimmedLine));
          }
        }
      }
    }
  }

  /**
   * Deep merge two objects
   * @param {Object} target - Target object
   * @param {Object} source - Source object
   */
  deepMerge(target, source) {
    const result = { ...target };

    for (const key in source) {
      if (source[key] && typeof source[key] === 'object' && !Array.isArray(source[key])) {
        if (result[key] && typeof result[key] === 'object' && !Array.isArray(result[key])) {
          result[key] = this.deepMerge(result[key], source[key]);
        } else {
          result[key] = source[key];
        }
      } else {
        result[key] = source[key];
      }
    }

    return result;
  }
}

/**
 * Parse a config.toml or config.user.toml written by writeCentralConfig.
 * Only handles the subset of TOML the installer produces: [core],
 * [modules.<code>], string/bool/number scalar values. [agents.*] and other
 * sections are ignored. Returns a plain object keyed by section name where
 * module sections use the bare code (e.g. "bmm"), not the full "modules.bmm".
 */
function parseCentralToml(content) {
  const result = {};
  let currentSection = null;

  for (const rawLine of content.split('\n')) {
    const line = rawLine.trim();
    if (!line || line.startsWith('#')) continue;

    const sectionMatch = line.match(/^\[([^\]]+)\]\s*$/);
    if (sectionMatch) {
      const name = sectionMatch[1];
      if (name === 'core') {
        currentSection = 'core';
      } else if (name.startsWith('modules.')) {
        currentSection = name.slice('modules.'.length);
      } else {
        currentSection = null;
      }
      if (currentSection && !result[currentSection]) {
        result[currentSection] = {};
      }
      continue;
    }

    if (!currentSection) continue;

    const kvMatch = line.match(/^([a-zA-Z_][a-zA-Z0-9_]*)\s*=\s*(.+)$/);
    if (!kvMatch) continue;

    const key = kvMatch[1];
    const raw = kvMatch[2].trim();
    let value;
    if (raw.startsWith('"') && raw.endsWith('"')) {
      value = raw.slice(1, -1).replaceAll(/\\(["\\nrbt])/g, (_, c) => ({ '"': '"', '\\': '\\', n: '\n', r: '\r', b: '\b', t: '\t' })[c]);
    } else if (raw === 'true') {
      value = true;
    } else if (raw === 'false') {
      value = false;
    } else if (raw !== '' && !isNaN(raw)) {
      value = Number(raw);
    } else {
      value = raw;
    }
    result[currentSection][key] = value;
  }

  return result;
}

module.exports = { OfficialModules };
